import type { RawQ } from "../types";
// Scholar tier (Mutaqaddim and ʿĀlim) hadith: terminology and grading, narrator criticism (jarḥ and taʿdīl), defects (ʿilal), modes of transmission, Companions as narrators, the canonical books and their commentaries. Draft content, needs scholarly review.
export const QS: RawQ[] = [
{ id: "xhd-001", s: "hadith", g: 4, d: 6, t: ["sahih-conditions", "ibn-al-salah"], src: "Ibn al-Ṣalāḥ, Muqaddima fī ʿUlūm al-Ḥadīth (ʿUlūm al-Ḥadīth), naw‘ 1 (al-ṣaḥīḥ)",
    en: ["What are the five conditions that Ibn al-Ṣalāḥ gives for a ṣaḥīḥ hadith (li-dhātihi)?", ["A continuous chain, upright narrators, precise narrators, absence of irregularity (shudhūdh) and absence of a hidden defect (ʿilla)", "Narration by at least four Companions, a famous narrator, a short chain, a known author and agreement with the Quran", "A chain of Madinan narrators, a legal ruling, a famous collection, a date and a witness", "Narration in a Ṣaḥīḥ collection, by two narrators, with the Prophet’s companions named, and a text in classical Arabic"], "Ibn al-Ṣalāḥ (d. 643 AH) defines the ṣaḥīḥ as a hadith with a connected chain (ittiṣāl al-sanad) of upright (ʿadl) and precise (ḍābiṭ) narrators from beginning to end, free from shudhūdh and ʿilla. If the precision of a narrator is lighter, the hadith is ḥasan li-dhātihi. This definition has been the basis of the later textbooks."],
    de: ["Welche fünf Bedingungen nennt Ibn aṣ-Ṣalāḥ für einen ṣaḥīḥ-Hadith (li-ḏātihi)?", ["Eine durchgehende Kette, redliche Überlieferer, präzise Überlieferer, Fehlen von Abweichung (šuḏūḏ) und Fehlen eines verborgenen Mangels (ʿilla)", "Überlieferung durch mindestens vier Gefährten, ein berühmter Überlieferer, eine kurze Kette, ein bekannter Autor und Übereinstimmung mit dem Koran", "Eine Kette medinensischer Überlieferer, ein Rechtsurteil, eine berühmte Sammlung, ein Datum und ein Zeuge", "Überlieferung in einer Ṣaḥīḥ-Sammlung durch zwei Überlieferer, mit Nennung der Gefährten des Propheten und einem Text in klassischem Arabisch"], "Ibn aṣ-Ṣalāḥ (gest. 643 n. H.) definiert den Ṣaḥīḥ als Hadith mit verbundener Kette (ittiṣāl as-sanad) redlicher (ʿadl) und präziser (ḍābiṭ) Überlieferer von Anfang bis Ende, frei von Šuḏūḏ und ʿIlla. Ist die Präzision eines Überlieferers geringer, ist der Hadith ḥasan li-ḏātihi. Diese Definition ist die Grundlage der späteren Lehrbücher."],
    ar: ["ما الشروط الخمسة التي يضعها ابن الصلاح للحديث الصحيح لذاته؟", ["اتصال السند وعدالة الرواة وضبطهم وانتفاء الشذوذ وانتفاء العلة", "رواية أربعة من الصحابة على الأقل وراوٍ مشهور وسند قصير ومؤلف معروف وموافقة القرآن", "سند من رواة مدنيين وحكم فقهي ومجموعة مشهورة وتاريخ وشاهد", "الورود في كتاب صحيح برواية اثنين مع تسمية أصحاب النبي ونص بعربية فصيحة"], "عرّف ابن الصلاح (ت 643هـ) الصحيح بأنه ما اتصل سنده بنقل العدل الضابط عن مثله إلى منتهاه من غير شذوذ ولا علة، فإن خفّ ضبط الراوي كان الحديث حسنًا لذاته، وصار هذا التعريف أساس الكتب المتأخرة."] },

  { id: "xhd-002", s: "hadith", g: 4, d: 7, t: ["tirmidhi", "terminology"], src: "Ibn Ḥajar, al-Nukat ʿalā Kitāb Ibn al-Ṣalāḥ; Ibn al-Ṣalāḥ, Muqaddima; al-Tirmidhī, Jāmiʿ and al-ʿIlal al-Ṣaghīr",
    en: ["What does al-Tirmidhī mean by ‘ḥasan ṣaḥīḥ’ for a single hadith, according to Ibn Ḥajar’s widely accepted explanation?", ["That it has two chains, one ḥasan and the other ṣaḥīḥ, or that the critic hesitated between the two grades", "That the hadith is higher than ṣaḥīḥ", "That the hadith is fabricated", "That it is a single-chain hadith with a Companion who is unknown"], "Ibn al-Ṣalāḥ asked how a hadith can be both and answered that al-Tirmidhī’s phrase applies to a hadith with two chains, so that it is ṣaḥīḥ by one and ḥasan by the other. Ibn Ḥajar added another possibility, that the critic could not decide between the two grades. If the hadith has only one chain, the phrase expresses that hesitation. The explanation is accepted because the grades differ in precision."],
    de: ["Was meint at-Tirmiḏī mit ‚ḥasan ṣaḥīḥ‘ für einen einzelnen Hadith nach Ibn Ḥaǧars weithin anerkannter Erklärung?", ["Dass er zwei Ketten hat, eine ḥasan und eine ṣaḥīḥ, oder dass der Kritiker zwischen den beiden Graden schwankte", "Dass der Hadith höher als ṣaḥīḥ ist", "Dass der Hadith erfunden ist", "Dass er ein Hadith mit einer Kette ist, deren Gefährte unbekannt ist"], "Ibn aṣ-Ṣalāḥ fragte, wie ein Hadith beides sein kann, und antwortete, at-Tirmiḏīs Wendung beziehe sich auf einen Hadith mit zwei Ketten, sodass er nach der einen ṣaḥīḥ und nach der anderen ḥasan sei. Ibn Ḥaǧar fügte eine weitere Möglichkeit hinzu, nämlich dass der Kritiker sich nicht zwischen den beiden Graden entscheiden konnte. Hat der Hadith nur eine Kette, drückt die Wendung dieses Schwanken aus. Die Erklärung gilt, weil die Grade sich in der Präzision unterscheiden."],
    ar: ["ماذا يعني الترمذي بقوله «حسن صحيح» في حديث واحد بحسب التوجيه المقبول عند ابن حجر؟", ["أن له إسنادين أحدهما حسن والآخر صحيح، أو أن الناقد تردد بين الحكمين", "أن الحديث فوق الصحيح", "أن الحديث موضوع", "أنه حديث بسند واحد في صحابيه جهالة"], "سأل ابن الصلاح كيف يكون الحديث حسنًا وصحيحًا معًا وأجاب بأن قول الترمذي يُحمل على حديث له إسنادان فيكون صحيحًا بأحدهما حسنًا بالآخر، وأضاف ابن حجر احتمال تردد الناقد بين الحكمين إن كان له إسناد واحد، ويُقبل التوجيه لأن الدرجتين تختلفان في الضبط."] },

  { id: "xhd-003", s: "hadith", g: 4, d: 6, t: ["mutawatir", "definitions"], src: "Ibn Ḥajar, Nukhbat al-Fikar and Nuzhat al-Naẓar; al-Suyūṭī, Qaṭf al-Azhār al-Mutanāthira fī al-Akhbār al-Mutawātira",
    en: ["Which statement about the mutawātir hadith is correct?", ["It is narrated by so many in every generation that agreement on falsehood is impossible; it is either verbal (lafẓī) or in meaning (maʿnawī), and al-Suyūṭī collected examples", "It is any hadith with two chains", "It is any hadith narrated by one Companion", "It is any hadith accepted by one scholar"], "The mutawātir yields certain knowledge. Scholars differ on the minimum number of narrators, but all insist on the impossibility of conspiracy. The verbal kind is rare, and the commonly cited example is the warning against lying about the Prophet. Examples of the maʿnawī kind include the raising of the hands in supplication and wiping over the khuffs. Al-Suyūṭī wrote Qaṭf al-Azhār on them."],
    de: ["Welche Aussage über den mutawātir-Hadith ist richtig?", ["Er wird in jeder Generation von so vielen überliefert, dass eine Übereinkunft zur Lüge unmöglich ist; er ist entweder wörtlich (lafẓī) oder dem Sinn nach (maʿnawī), und as-Suyūṭī sammelte Beispiele", "Er ist jeder Hadith mit zwei Ketten", "Er ist jeder Hadith, den ein Gefährte überliefert", "Er ist jeder Hadith, den ein Gelehrter annimmt"], "Der Mutawātir liefert sicheres Wissen. Die Gelehrten sind sich über die Mindestzahl der Überlieferer uneins, bestehen aber alle auf der Unmöglichkeit einer Verabredung. Die wörtliche Art ist selten, und das häufig genannte Beispiel ist die Warnung davor, über den Propheten zu lügen. Beispiele der maʿnawī-Art sind das Erheben der Hände im Bittgebet und das Bestreichen der Ledersocken. As-Suyūṭī schrieb Qaṭf al-Azhār darüber."],
    ar: ["أي عبارة عن الحديث المتواتر صحيحة؟", ["يرويه في كل طبقة جمع يستحيل تواطؤهم على الكذب، وهو لفظي أو معنوي، وجمع السيوطي أمثلته", "هو كل حديث له إسنادان", "هو كل حديث يرويه صحابي واحد", "هو كل حديث قبله عالم واحد"], "المتواتر يفيد العلم القطعي، ويختلف العلماء في أقل عدد لكنهم يتفقون على استحالة التواطؤ، واللفظي قليل ومن أشهر أمثلته التحذير من الكذب على النبي ﷺ، ومن المعنوي رفع اليدين في الدعاء والمسح على الخفين، وقد ألّف السيوطي «قطف الأزهار» فيها."] },

  { id: "xhd-004", s: "hadith", g: 4, d: 6, t: ["classification", "gharib-aziz-mashhur"], src: "Ibn Ḥajar, Nukhbat al-Fikar and Nuzhat al-Naẓar",
    en: ["How does Ibn Ḥajar’s Nukhba define the mashhūr, the ʿazīz and the gharīb hadith?", ["Mashhūr has three or more narrators at each level; ʿazīz not fewer than two at any level; gharīb a single narrator at some level", "Mashhūr has one narrator; ʿazīz two; gharīb ten", "Mashhūr is a hadith from Makka; ʿazīz from Madīna; gharīb from Baṣra", "All three mean fabricated"], "In the Nukhba, the mashhūr is what has three or more chains but has not reached the level of mutawātir; the ʿazīz is the hadith that does not have fewer than two narrators at any stage; the gharīb is one narrated by a single narrator at some stage. Al-Suyūṭī and others use ‘mustafīḍ’ for what many call mashhūr; the three terms describe the number of narrators, not the grade of the hadith."],
    de: ["Wie definiert Ibn Ḥaǧars Nuḫba den mašhūr-, den ʿazīz- und den ġarīb-Hadith?", ["Mašhūr hat auf jeder Stufe drei oder mehr Überlieferer; ʿazīz auf keiner Stufe weniger als zwei; ġarīb auf irgendeiner Stufe einen einzigen Überlieferer", "Mašhūr hat einen Überlieferer; ʿazīz zwei; ġarīb zehn", "Mašhūr ist ein Hadith aus Mekka; ʿazīz aus Medina; ġarīb aus Basra", "Alle drei bedeuten erfunden"], "In der Nuḫba ist der Mašhūr, was drei oder mehr Ketten hat, aber die Stufe des Mutawātir nicht erreicht; der ʿAzīz ist der Hadith, der auf keiner Stufe weniger als zwei Überlieferer hat; der Ġarīb wird auf irgendeiner Stufe von einem einzigen Überlieferer überliefert. As-Suyūṭī und andere gebrauchen ‚mustafīḍ‘ für das, was viele mašhūr nennen; die drei Begriffe beschreiben die Zahl der Überlieferer, nicht den Grad des Hadith."],
    ar: ["كيف تعرّف «نخبة الفكر» لابن حجر الحديث المشهور والعزيز والغريب؟", ["المشهور ما له ثلاثة طرق فأكثر في كل طبقة، والعزيز ما لا يقل رواته عن اثنين في طبقة من الطبقات، والغريب ما انفرد به راوٍ واحد في طبقة", "المشهور براوٍ واحد والعزيز باثنين والغريب بعشرة", "المشهور من مكة والعزيز من المدينة والغريب من البصرة", "الثلاثة بمعنى الموضوع"], "في النخبة المشهور ما له ثلاثة طرق فأكثر ولم يبلغ التواتر، والعزيز ما لا يقل رواته عن اثنين في أي طبقة، والغريب ما رواه راوٍ واحد في طبقة ما. ويستعمل السيوطي وغيره «المستفيض» لما يسميه كثيرون مشهورًا، والمصطلحات الثلاثة في عدد الرواة لا في درجة الصحة."] },

  { id: "xhd-005", s: "hadith", g: 4, d: 7, t: ["sahihayn", "conditions"], src: "Muslim, Ṣaḥīḥ, introduction (muqaddima); Ibn Ḥajar, Hady al-Sārī, introduction; al-Nawawī, Sharḥ Ṣaḥīḥ Muslim, introduction",
    en: ["What is the classical contrast between the conditions of al-Bukhārī and Muslim regarding the link between a narrator and his teacher?", ["Al-Bukhārī required proof of an actual meeting (liqāʾ); Muslim was satisfied with the possibility of meeting (muʿāṣara) when the narrator is not a mudallis", "Muslim required proof of an actual meeting, and al-Bukhārī was satisfied with contemporaneity", "Both required three meetings", "Neither considered the link, only the text"], "In the introduction to his Ṣaḥīḥ, Muslim argues against those who demanded proof of meeting and says contemporaneity with the possibility of meeting is enough for a non-mudallis who uses ‘from’. Al-Bukhārī, with ʿAlī ibn al-Madīnī, required proof of at least one meeting for the muʿanʿan chains. Scholars say this makes the Bukhārī conditions stricter, though Muslim’s tarjīḥ also has its supporters."],
    de: ["Worin besteht der klassische Gegensatz zwischen den Bedingungen von al-Buḫārī und Muslim hinsichtlich der Verbindung zwischen einem Überlieferer und seinem Lehrer?", ["Al-Buḫārī verlangte den Nachweis einer tatsächlichen Begegnung (liqāʾ); Muslim begnügte sich mit der Möglichkeit der Begegnung (muʿāṣara), wenn der Überlieferer kein Mudallis ist", "Muslim verlangte den Nachweis einer tatsächlichen Begegnung, und al-Buḫārī begnügte sich mit Zeitgenossenschaft", "Beide verlangten drei Begegnungen", "Keiner beachtete die Verbindung, nur den Text"], "In der Einleitung zu seinem Ṣaḥīḥ argumentiert Muslim gegen diejenigen, die den Nachweis einer Begegnung forderten, und sagt, Zeitgenossenschaft mit der Möglichkeit der Begegnung genüge bei einem Nicht-Mudallis, der ‚von‘ gebraucht. Al-Buḫārī verlangte mit ʿAlī ibn al-Madīnī den Nachweis mindestens einer Begegnung bei den muʿanʿan-Ketten. Die Gelehrten sagen, das mache die Bedingungen al-Buḫārīs strenger, doch auch Muslims Ansatz hat Befürworter."],
    ar: ["ما التباين الكلاسيكي بين شرط البخاري وشرط مسلم في الصلة بين الراوي وشيخه؟", ["اشترط البخاري ثبوت اللقاء وتساهل مسلم بإمكان اللقاء (المعاصرة) إذا لم يكن الراوي مدلسًا", "اشترط مسلم ثبوت اللقاء واكتفى البخاري بالمعاصرة", "اشترط كلاهما ثلاثة لقاءات", "لم يلتفت أحدهما إلى الصلة بل إلى المتن فقط"], "ناظر مسلم في مقدمة صحيحه من اشترط ثبوت اللقاء وقال إن المعاصرة مع إمكان اللقاء تكفي في غير المدلس إذا قال «عن»، واشترط البخاري مع علي بن المديني ثبوت اللقاء ولو مرة في الأسانيد المعنعنة، ويقول العلماء إن هذا يجعل شرط البخاري أشد، وإن كان لاختيار مسلم أنصار."] },

  { id: "xhd-006", s: "hadith", g: 4, d: 7, t: ["mursal", "shafii-conditions"], tr: ["shafii", "hanafi", "maliki", "comparative"], src: "al-Shāfiʿī, al-Risāla, bāb khabar al-wāḥid; Ibn al-Ṣalāḥ, Muqaddima, naw‘ 5; al-ʿAlāʾī, Jāmiʿ al-Taḥṣīl",
    en: ["What are the views of the schools and of al-Shāfiʿī on using the mursal hadith (when a Successor cites the Prophet directly) as evidence?", ["Abū Ḥanīfa and Mālik accept it; most hadith critics reject it as weak; al-Shāfiʿī accepts the mursal of a senior Successor only if conditions are met, such as being supported by another chain", "All schools accept every mursal without condition", "All schools reject every mursal without exception", "Only al-Shāfiʿī accepted it"], "The mursal omits the Companion and so a link is missing. Abū Ḥanīfa and Mālik (and Aḥmad in one report) accept it from trustworthy narrators; most muḥaddithūn consider it weak for the missing link. Al-Shāfiʿī in the Risāla accepts the mursal of senior Successors such as Saʿīd ibn al-Musayyab if it is also confirmed by a musnad chain, by another mursal from a different source, by a Companion’s statement or by most scholars’ ruling."],
    de: ["Wie lauten die Ansichten der Schulen und aš-Šāfiʿīs zur Verwendung des mursal-Hadith (wenn ein Nachfolger den Propheten unmittelbar zitiert) als Beleg?", ["Abū Ḥanīfa und Mālik nehmen ihn an; die meisten Hadithkritiker verwerfen ihn als schwach; aš-Šāfiʿī akzeptiert den Mursal eines hohen Nachfolgers nur bei erfüllten Bedingungen, etwa wenn er durch eine andere Kette gestützt wird", "Alle Schulen akzeptieren jeden Mursal ohne Bedingung", "Alle Schulen verwerfen jeden Mursal ausnahmslos", "Nur aš-Šāfiʿī nahm ihn an"], "Der Mursal lässt den Gefährten aus, sodass ein Glied fehlt. Abū Ḥanīfa und Mālik (und Aḥmad nach einem Bericht) nehmen ihn von vertrauenswürdigen Überlieferern an; die meisten Muḥaddiṯūn halten ihn wegen des fehlenden Glieds für schwach. Aš-Šāfiʿī nimmt in der Risāla den Mursal hoher Nachfolger wie Saʿīd ibn al-Musayyab an, wenn er außerdem durch eine Musnad-Kette, einen anderen Mursal aus anderer Quelle, eine Aussage eines Gefährten oder das Urteil der meisten Gelehrten bestätigt wird."],
    ar: ["ما مواقف المذاهب والشافعي من الاحتجاج بالحديث المرسل (إذا أسنده التابعي إلى النبي ﷺ مباشرة)؟", ["قبله أبو حنيفة ومالك وردّه أكثر المحدثين لضعفه، وقبل الشافعي مرسل كبار التابعين بشروط كتأييده بسند آخر", "تقبله المذاهب كلها بلا شرط", "تردّه المذاهب كلها دون استثناء", "قبله الشافعي وحده"], "المرسل ساقط منه الصحابي فيه انقطاع، وقبله أبو حنيفة ومالك (وأحمد في رواية) من الثقات، وردّه أكثر المحدثين لسقوط الواسطة، وقبل الشافعي في «الرسالة» مرسل كبار التابعين كابن المسيب إذا اعتضد بمسند أو بمرسل آخر من أصل مختلف أو بقول صحابي أو بفتوى أكثر أهل العلم."] },

  { id: "xhd-007", s: "hadith", g: 4, d: 7, t: ["tadlis", "types"], src: "Ibn Ḥajar, Ṭabaqāt al-Mudallisīn (Taʿrīf Ahl al-Taqdīs); Ibn al-Ṣalāḥ, Muqaddima, naw‘ 12",
    en: ["Which statement correctly describes the types of tadlīs?", ["Tadlīs al-isnād (concealing the narrator from whom one actually took), tadlīs al-shuyūkh (naming one’s teacher by an unfamiliar name) and tadlīs al-taswiya (omitting a weak narrator between two reliable ones)", "Tadlīs al-matn, tadlīs al-ḥurūf and tadlīs al-ṣawt", "Tadlīs al-ṣaḥāba, tadlīs al-tābiʿīn and tadlīs al-fuqahāʾ", "Tadlīs al-qiblā, tadlīs al-ṣalā and tadlīs al-zakā"], "In tadlīs al-isnād the narrator reports from a contemporary with a word that suggests hearing, though he did not hear from him. In tadlīs al-shuyūkh the narrator gives his teacher a name or title that obscures him. In tadlīs al-taswiya, associated with Baqiyya ibn al-Walīd and al-Walīd ibn Muslim, the narrator drops the weak narrator between two reliable ones, making the chain look strong. Taswiya is the worst, since even the statement of hearing between the surviving pair is correct."],
    de: ["Welche Aussage beschreibt die Arten des Tadlīs richtig?", ["Tadlīs al-isnād (Verbergen des Überlieferers, von dem man tatsächlich nahm), tadlīs aš-šuyūḫ (den Lehrer mit unbekanntem Namen nennen) und tadlīs at-taswiya (Auslassen eines schwachen Überlieferers zwischen zwei zuverlässigen)", "Tadlīs al-matn, tadlīs al-ḥurūf und tadlīs aṣ-ṣaut", "Tadlīs aṣ-ṣaḥāba, tadlīs at-tābiʿīn und tadlīs al-fuqahāʾ", "Tadlīs al-qibla, tadlīs aṣ-ṣalā und tadlīs az-zakā"], "Beim Tadlīs al-isnād berichtet der Überlieferer von einem Zeitgenossen mit einem Wort, das Hören nahelegt, obwohl er nicht von ihm hörte. Beim Tadlīs aš-šuyūḫ gibt der Überlieferer seinem Lehrer einen Namen oder Titel, der ihn verschleiert. Beim Tadlīs at-taswiya, mit Baqiyya ibn al-Walīd und al-Walīd ibn Muslim verbunden, lässt der Überlieferer den schwachen Überlieferer zwischen zwei zuverlässigen weg, sodass die Kette stark aussieht. Die Taswiya ist die schlimmste, da selbst die Hörangabe zwischen dem verbleibenden Paar zutrifft."],
    ar: ["أي عبارة تصف أنواع التدليس على الوجه الصحيح؟", ["تدليس الإسناد (إخفاء من أخذ عنه حقيقةً) وتدليس الشيوخ (تسمية الشيخ باسم غير مشهور) وتدليس التسوية (حذف راوٍ ضعيف بين ثقتين)", "تدليس المتن وتدليس الحروف وتدليس الصوت", "تدليس الصحابة وتدليس التابعين وتدليس الفقهاء", "تدليس القبلة وتدليس الصلاة وتدليس الزكاة"], "في تدليس الإسناد يروي الراوي عمن عاصره بلفظ يوهم السماع ولم يسمع منه، وفي تدليس الشيوخ يسمّي شيخه باسم أو لقب لا يُعرف به، وفي تدليس التسوية المنسوب إلى بقية بن الوليد والوليد بن مسلم يحذف الراوي الضعيف بين ثقتين فيبدو الإسناد قويًّا، وهو أشد أنواعه لأن التصريح بالسماع بين الباقيين صحيح."] },

  { id: "xhd-008", s: "hadith", g: 4, d: 7, t: ["tadlis", "ibn-hajar-ranks"], src: "Ibn Ḥajar, Ṭabaqāt al-Mudallisīn (Taʿrīf Ahl al-Taqdīs bi-Marātib al-Mawṣūfīn bi-l-Tadlīs)",
    en: ["How does Ibn Ḥajar’s Ṭabaqāt al-Mudallisīn organise the narrators known for tadlīs?", ["In five ranks, from those who rarely did it or only from reliable sources (whose ʿanʿana is accepted) to those whose ʿanʿana is rejected unless they state hearing", "In two ranks, Makkan and Madinan", "In three ranks, Companions, Successors and their followers", "In ten ranks by the number of their students"], "Ibn Ḥajar sorted the mudallisīn into five ranks: those who did tadlīs rarely or who are not known for it; those whose tadlīs is accepted because they only did it from reliable teachers; those who did it often, accepted only with a statement of hearing; those who were disqualified for their tadlīs from the weak; and those whose ʿanʿana is rejected even for other reasons. The ranking tells a critic how to handle a ‘from’ in a chain."],
    de: ["Wie ordnet Ibn Ḥaǧars Ṭabaqāt al-Mudallisīn die für Tadlīs bekannten Überlieferer?", ["In fünf Rängen, von denen, die es selten oder nur von zuverlässigen Quellen taten (deren ʿanʿana angenommen wird), bis zu denen, deren ʿanʿana abgelehnt wird, wenn sie das Hören nicht angeben", "In zwei Rängen, mekkanisch und medinensisch", "In drei Rängen: Gefährten, Nachfolger und deren Nachfolger", "In zehn Rängen nach der Zahl ihrer Schüler"], "Ibn Ḥaǧar ordnete die Mudallisīn in fünf Ränge: die, die selten Tadlīs übten oder nicht dafür bekannt sind; die, deren Tadlīs angenommen wird, weil sie es nur von zuverlässigen Lehrern übten; die, die es oft taten und nur mit Hörangabe angenommen werden; die, die wegen Tadlīs von Schwachen disqualifiziert wurden; und die, deren ʿanʿana auch aus anderen Gründen abgelehnt wird. Die Rangordnung zeigt einem Kritiker, wie ein ‚von‘ in einer Kette zu behandeln ist."],
    ar: ["كيف ينظّم ابن حجر في «طبقات المدلسين» الرواة الموصوفين بالتدليس؟", ["في خمس مراتب من قليل التدليس أو الذي لا يدلس إلا عن ثقة (وتُقبل عنعنته) إلى من تُردّ عنعنته ما لم يصرح بالسماع", "في مرتبتين: مكية ومدنية", "في ثلاث مراتب: الصحابة والتابعون وأتباعهم", "في عشر مراتب بحسب عدد التلاميذ"], "رتب ابن حجر المدلسين في خمس مراتب: من لم يوصف به إلا نادرًا، ومن احتُمل تدليسه لأنه لا يدلس إلا عن ثقة، ومن أكثر منه فلا يُقبل إلا بالتصريح بالسماع، ومن اتُّفق على ضعف عنعنته لتدليسه عن الضعفاء، ومن رُدّت عنعنته لأمر آخر مع التدليس. والمراتب تبيّن للناقد كيف يعامل «عن» في الإسناد."] },

  { id: "xhd-009", s: "hadith", g: 4, d: 7, t: ["shadh-munkar", "definitions"], src: "Ibn Ḥajar, Nukhbat al-Fikar and Nuzhat al-Naẓar; al-Shāfiʿī as cited in Ibn al-Ṣalāḥ, Muqaddima, naw‘ 7–8",
    en: ["How does Ibn Ḥajar’s Nukhba distinguish shādhdh from munkar?", ["Shādhdh is a hadith of an acceptable narrator that contradicts a more reliable one; munkar is a hadith of a weak narrator that contradicts a reliable one", "Shādhdh is a hadith with a long chain; munkar is a hadith with a short chain", "Shādhdh is any rare hadith; munkar is any hadith of a Madinan", "Both mean exactly the same"], "Ibn Ḥajar adopts the criterion of opposition: if a maqbūl narrator conflicts with someone more reliable, his report is shādhdh and the report of the more reliable is maḥfūẓ. If the opposed narrator is weak, his report is munkar, and the other is maʿrūf. Al-Shāfiʿī’s older definition of shādhdh is a narrator’s opposition to what the people have transmitted, and others (like al-Ḥākim) defined it as a lone report by a trustworthy narrator."],
    de: ["Wie unterscheidet Ibn Ḥaǧars Nuḫba šāḏḏ von munkar?", ["Šāḏḏ ist ein Hadith eines annehmbaren Überlieferers, der einem zuverlässigeren widerspricht; munkar ist ein Hadith eines schwachen Überlieferers, der einem zuverlässigen widerspricht", "Šāḏḏ ist ein Hadith mit langer Kette; munkar ein Hadith mit kurzer Kette", "Šāḏḏ ist jeder seltene Hadith; munkar jeder Hadith eines Medinensers", "Beide bedeuten genau dasselbe"], "Ibn Ḥaǧar übernimmt das Kriterium des Widerspruchs: Widerspricht ein annehmbarer (maqbūl) Überlieferer einem Zuverlässigeren, ist sein Bericht šāḏḏ und der des Zuverlässigeren maḥfūẓ. Ist der Widersprechende schwach, ist sein Bericht munkar und der andere maʿrūf. Aš-Šāfiʿīs ältere Definition des Šāḏḏ ist die Abweichung eines Überlieferers von dem, was die Leute überliefert haben, und andere (wie al-Ḥākim) definierten ihn als Einzelbericht eines vertrauenswürdigen Überlieferers."],
    ar: ["كيف تفرّق «نخبة الفكر» لابن حجر بين الشاذ والمنكر؟", ["الشاذ ما رواه مقبول وخالف من هو أوثق منه، والمنكر ما رواه ضعيف وخالف الثقة", "الشاذ حديث بسند طويل والمنكر حديث بسند قصير", "الشاذ كل حديث نادر والمنكر كل حديث مدني", "هما بمعنى واحد تمامًا"], "اعتمد ابن حجر معيار المخالفة: إذا خالف الراوي المقبول من هو أوثق منه فروايته شاذة ورواية الأوثق محفوظة، وإذا كان المخالِف ضعيفًا فروايته منكرة والأخرى معروفة. وتعريف الشافعي الأقدم للشاذ أن يروي الثقة ما يخالف الناس، وعرّفه غيره كالحاكم بتفرد الثقة."] },

  { id: "xhd-010", s: "hadith", g: 4, d: 6, t: ["illa", "classical-works"], src: "Ibn Rajab, Sharḥ ʿIlal al-Tirmidhī; al-Dāraquṭnī, al-ʿIlal; Ibn Abī Ḥātim, ʿIlal al-Ḥadīth; ʿAlī ibn al-Madīnī, ʿIlal al-Ḥadīth",
    en: ["What is an ʿilla in the science of hadith, and who was an early master of it?", ["A hidden, subtle defect in a hadith that appears sound on the surface; ʿAlī ibn al-Madīnī, Yaḥyā ibn Maʿīn and Aḥmad were early masters", "A visible weakness such as an unknown narrator; al-Bukhārī was the first writer on it", "A decoration of the chain; Ibn Ḥajar was the first", "A name for a fabricated hadith; al-Suyūṭī was the first"], "An ʿilla (also mulalla) is a defect that is not obvious and is found only by experts through collecting chains, such as a hidden break or an error in attributing the hadith to a Companion. ʿAlī ibn al-Madīnī, Yaḥyā ibn Maʿīn, Aḥmad, al-Bukhārī, Abū Ḥātim al-Rāzī and later al-Dāraquṭnī are masters, and works on ʿilal include those of Ibn Abī Ḥātim and al-Dāraquṭnī."],
    de: ["Was ist eine ʿilla in der Hadithwissenschaft, und wer war ein früher Meister darin?", ["Ein verborgener, feiner Mangel eines Hadith, der äußerlich gesund erscheint; ʿAlī ibn al-Madīnī, Yaḥyā ibn Maʿīn und Aḥmad waren frühe Meister", "Eine sichtbare Schwäche wie ein unbekannter Überlieferer; al-Buḫārī war der erste Autor darüber", "Eine Verzierung der Kette; Ibn Ḥaǧar war der erste", "Ein Name für einen erfundenen Hadith; as-Suyūṭī war der erste"], "Eine ʿilla (auch muʿallal) ist ein nicht offensichtlicher Mangel, den nur Kenner durch das Zusammentragen von Ketten finden, etwa ein verborgener Bruch oder ein Irrtum bei der Zuschreibung des Hadith an einen Gefährten. ʿAlī ibn al-Madīnī, Yaḥyā ibn Maʿīn, Aḥmad, al-Buḫārī, Abū Ḥātim ar-Rāzī und später ad-Dāraquṭnī sind Meister, und zu den Werken über ʿIlal gehören die von Ibn Abī Ḥātim und ad-Dāraquṭnī."],
    ar: ["ما العلة في علم الحديث ومن كان من أوائل أئمتها؟", ["عيب خفي دقيق في حديث ظاهره السلامة، ومن أئمتها المبكرين علي بن المديني ويحيى بن معين وأحمد", "ضعف ظاهر كجهالة راوٍ، وأول من كتب فيها البخاري", "زخرف في الإسناد، وأول من كتب فيها ابن حجر", "اسم للحديث المختلق، وأول من كتب فيها السيوطي"], "العلة قدح خفي لا يدركه إلا الجهابذة بجمع الطرق، كانقطاع خفي أو وهم في نسبة الحديث إلى صحابي، وأئمتها علي بن المديني ويحيى بن معين وأحمد والبخاري وأبو حاتم الرازي ثم الدارقطني، ومن الكتب في العلل علل ابن أبي حاتم وعلل الدارقطني."] },

  { id: "xhd-011", s: "hadith", g: 4, d: 7, t: ["jarh-tadil", "ranks"], src: "Ibn Ḥajar, Taqrīb al-Tahdhīb, introduction; Ibn Abī Ḥātim, al-Jarḥ wa-l-Taʿdīl, introduction",
    en: ["How does Ibn Ḥajar arrange the narrators in his Taqrīb al-Tahdhīb?", ["In twelve ranks from the Companions through the Successors and their followers down to the weakest, with a single phrase of judgement for each", "In two ranks, trustworthy and untrustworthy", "In four ranks by the Companion they narrated from", "In seven ranks by the Quran reader they followed"], "The Taqrīb begins with the Companions and then orders narrators in twelve ṭabaqāt of generation and then by status, giving each a concise judgement (such as thiqa, ṣadūq, layyin, matrūk). Ibn Abī Ḥātim’s earlier al-Jarḥ wa-l-Taʿdīl set four ranks of taʿdīl and four ranks of jarḥ; the Taqrīb is a refined summary of Tahdhīb al-Kamāl of al-Mizzī."],
    de: ["Wie ordnet Ibn Ḥaǧar die Überlieferer in seinem Taqrīb at-Tahḏīb?", ["In zwölf Rängen von den Gefährten über die Nachfolger und deren Nachfolger bis zu den schwächsten, mit je einer knappen Beurteilung", "In zwei Rängen, vertrauenswürdig und nicht vertrauenswürdig", "In vier Rängen nach dem Gefährten, von dem sie überlieferten", "In sieben Rängen nach dem Koranleser, dem sie folgten"], "Der Taqrīb beginnt mit den Gefährten und ordnet dann die Überlieferer in zwölf Ṭabaqāt nach Generation und dann nach Rang und gibt jedem eine knappe Beurteilung (wie ṯiqa, ṣadūq, layyin, matrūk). Ibn Abī Ḥātims früheres al-Ǧarḥ wa-t-Taʿdīl legte vier Ränge des Taʿdīl und vier des Ǧarḥ fest; der Taqrīb ist eine verfeinerte Zusammenfassung von al-Mizzīs Tahḏīb al-Kamāl."],
    ar: ["كيف يرتب ابن حجر الرواة في «تقريب التهذيب»؟", ["في اثنتي عشرة مرتبة من الصحابة فالتابعين وأتباعهم إلى أضعفهم مع حكم موجز لكل راوٍ", "في مرتبتين: ثقات وغير ثقات", "في أربع مراتب بحسب الصحابي الذي رووا عنه", "في سبع مراتب بحسب القارئ الذي اتبعوه"], "يبدأ التقريب بالصحابة ثم يرتب الرواة في اثنتي عشرة طبقة بحسب الجيل ثم الرتبة ويعطي كلًّا حكمًا موجزًا (ثقة، صدوق، لين، متروك...). وكان ابن أبي حاتم في «الجرح والتعديل» قد جعل أربع مراتب للتعديل وأربعًا للجرح، والتقريب خلاصة محررة لـ«تهذيب الكمال» للمزي."] },

  { id: "xhd-012", s: "hadith", g: 4, d: 6, t: ["jarh-tadil", "conflict-rules"], src: "Ibn al-Ṣalāḥ, Muqaddima, naw‘ 23; al-Khaṭīb al-Baghdādī, al-Kifāya fī ʿIlm al-Riwāya",
    en: ["What do most hadith scholars hold when an explained criticism (jarḥ mufassar) conflicts with a general praise (taʿdīl) of a narrator?", ["The explained criticism takes priority, since the critic knows something the praiser did not", "The praise always takes priority", "The two cancel out and the narrator is accepted", "The opinion of the later critic always prevails"], "The majority say that jarḥ mufassar outweighs taʿdīl because it adds knowledge. Some scholars add the condition that the reason of the criticism must be one that really damages, since critics may differ about what counts as a flaw. If the criticism is not explained, praise by a recognised critic is preferred. Al-Khaṭīb and Ibn al-Ṣalāḥ state the rule."],
    de: ["Was halten die meisten Hadithgelehrten, wenn eine begründete Kritik (ǧarḥ mufassar) einem allgemeinen Lob (taʿdīl) eines Überlieferers widerspricht?", ["Die begründete Kritik hat Vorrang, da der Kritiker etwas weiß, was der Lobende nicht wusste", "Das Lob hat immer Vorrang", "Beide heben sich auf, und der Überlieferer wird angenommen", "Die Meinung des späteren Kritikers setzt sich immer durch"], "Die Mehrheit sagt, ǧarḥ mufassar wiege schwerer als taʿdīl, weil es Wissen hinzufügt. Manche fügen die Bedingung hinzu, dass der Grund der Kritik ein wirklich schädlicher sein muss, da Kritiker uneins sein können, was ein Mangel ist. Ist die Kritik nicht begründet, wird das Lob eines anerkannten Kritikers bevorzugt. Al-Ḫaṭīb und Ibn aṣ-Ṣalāḥ halten die Regel fest."],
    ar: ["ماذا يرى أكثر المحدثين حين يتعارض جرح مفسَّر مع تعديل عام لراوٍ؟", ["الجرح المفسَّر مقدَّم لأن الجارح عنده زيادة علم لم يعلمها المعدِّل", "التعديل مقدَّم دائمًا", "يتساقطان فيُقبل الراوي", "رأي الناقد المتأخر هو الراجح دائمًا"], "قال الجمهور إن الجرح المفسر مقدم على التعديل لأنه يزيد علمًا، واشترط بعضهم أن يكون سبب الجرح قادحًا حقًّا لأن النقاد قد يختلفون فيما يعدّ عيبًا، وإذا لم يُفسَّر الجرح قُدّم تعديل الناقد المعتبر. وقد ذكر الخطيب وابن الصلاح القاعدة."] },

  { id: "xhd-013", s: "hadith", g: 4, d: 7, t: ["jarh-tadil", "critics-strictness"], src: "al-Dhahabī, Dhikr Man Yuʿtamad Qawluhu fī al-Jarḥ wa-l-Taʿdīl; al-Dhahabī, al-Mūqiẓa; Ibn Ḥajar, Lisān al-Mīzān, introduction",
    en: ["How do hadith scholars classify the critics of narrators by their strictness?", ["As strict (mutashaddid) such as Ibn Maʿīn and Ibn al-Qaṭṭān, lenient (mutasāhil) such as al-Tirmidhī and al-Ḥākim, and moderate (muʿtadil) such as Aḥmad and al-Bukhārī", "All critics are equally strict", "As Makkan, Madinan and Baṣran critics", "As early and late critics only"], "Al-Dhahabī classified the critics into those who are severe in criticism, those who are lenient and the moderate. A strict critic’s weakening of a narrator must be examined; a lenient critic’s authentication is received with caution. The classification guides how to weigh conflicting judgements. Ibn Ḥibbān is also known for leniency in authenticating unknown narrators."],
    de: ["Wie klassifizieren Hadithgelehrte die Kritiker von Überlieferern nach ihrer Strenge?", ["Als streng (mutašaddid) wie Ibn Maʿīn und Ibn al-Qaṭṭān, nachsichtig (mutasāhil) wie at-Tirmiḏī und al-Ḥākim und maßvoll (muʿtadil) wie Aḥmad und al-Buḫārī", "Alle Kritiker sind gleich streng", "Als mekkanische, medinensische und basrische Kritiker", "Nur als frühe und späte Kritiker"], "Adh-Dhahabī teilte die Kritiker in solche, die streng in der Kritik sind, solche, die nachsichtig sind, und die Maßvollen. Die Schwächung eines Überlieferers durch einen strengen Kritiker muss geprüft werden; die Beglaubigung durch einen nachsichtigen wird mit Vorsicht aufgenommen. Die Einteilung leitet an, widersprüchliche Urteile zu gewichten. Auch Ibn Ḥibbān ist für Nachsicht bei der Beglaubigung unbekannter Überlieferer bekannt."],
    ar: ["كيف يصنف المحدثون نقاد الرواة بحسب تشددهم؟", ["متشددون كابن معين وابن القطان، ومتساهلون كالترمذي والحاكم، ومعتدلون كأحمد والبخاري", "كل النقاد متساوون في الشدة", "نقاد مكيون ومدنيون وبصريون", "نقاد متقدمون ومتأخرون فقط"], "قسّم الذهبي النقاد إلى متعنت في الجرح ومتساهل ومعتدل، فيُفحص تضعيف المتشدد ويُتلقى توثيق المتساهل بحذر، والتقسيم يعين على الترجيح بين الأحكام المتعارضة. ويُعرف ابن حبان أيضًا بالتساهل في توثيق المجاهيل."] },

  { id: "xhd-014", s: "hadith", g: 4, d: 6, t: ["jarh-tadil", "companions"], tr: ["sunni"], src: "Ibn al-Ṣalāḥ, Muqaddima, naw‘ 39 (maʿrifat al-ṣaḥāba); Ibn Ḥajar, al-Iṣāba fī Tamyīz al-Ṣaḥāba, introduction; al-Khaṭīb al-Baghdādī, al-Kifāya",
    en: ["What is the position of the Sunni scholars of hadith on the uprightness (ʿadāla) of the Companions?", ["All Companions are considered upright for narration; one does not need to investigate their uprightness, though their individual reports are still examined for accuracy of transmission", "All Companions must be investigated like later narrators", "Only the first four caliphs are upright", "Only those who fought in Badr are upright"], "Ahl al-Sunna hold that the Companions are all ʿudūl, as God praised them in the Quran and the Prophet bore witness to them, so their uprightness is not subject to assessment. This does not mean they were infallible or that every attribution to a Companion is correct: the chain up to the Companion is still examined. Al-Khaṭīb and Ibn al-Ṣalāḥ discuss the rule."],
    de: ["Welche Position vertreten die sunnitischen Hadithgelehrten zur Redlichkeit (ʿadāla) der Gefährten?", ["Alle Gefährten gelten als redlich für die Überlieferung; ihre Redlichkeit braucht nicht untersucht zu werden, doch ihre einzelnen Berichte werden weiterhin auf Genauigkeit der Überlieferung geprüft", "Alle Gefährten müssen wie spätere Überlieferer untersucht werden", "Nur die ersten vier Kalifen sind redlich", "Nur die Teilnehmer von Badr sind redlich"], "Ahl as-Sunna vertreten, dass alle Gefährten ʿudūl sind, da Gott sie im Koran lobte und der Prophet für sie Zeugnis ablegte; ihre Redlichkeit unterliegt daher keiner Beurteilung. Das bedeutet nicht, dass sie unfehlbar waren oder dass jede Zuschreibung an einen Gefährten stimmt: Die Kette bis zum Gefährten wird weiterhin geprüft. Al-Ḫaṭīb und Ibn aṣ-Ṣalāḥ erörtern die Regel."],
    ar: ["ما موقف أهل السنة من المحدثين في عدالة الصحابة؟", ["الصحابة كلهم عدول في الرواية فلا يُبحث عن عدالتهم، مع بقاء فحص الأسانيد إليهم والتحقق من دقة نقل أخبارهم", "يجب فحص الصحابة جميعًا كالرواة المتأخرين", "الخلفاء الأربعة وحدهم عدول", "من شهد بدرًا وحدهم عدول"], "يرى أهل السنة أن الصحابة كلهم عدول لثناء الله عليهم في القرآن وشهادة النبي ﷺ لهم فلا يُبحث عن عدالتهم، وليس معنى ذلك العصمة ولا صحة كل نسبة إلى صحابي، فالسند إلى الصحابي يُفحص. وقد بحث ذلك الخطيب وابن الصلاح."] },

  { id: "xhd-015", s: "hadith", g: 4, d: 7, t: ["riwaya-bi-l-mana", "conditions"], tr: ["comparative"], src: "Ibn al-Ṣalāḥ, Muqaddima, naw‘ 25; al-Khaṭīb al-Baghdādī, al-Kifāya; al-Suyūṭī, Tadrīb al-Rāwī",
    en: ["What is the majority view on narrating a hadith by meaning (riwāya bi-l-maʿnā) rather than by exact wording?", ["It is permitted for a narrator who knows Arabic and the meanings, and understands what changes the sense, while verbatim narration is preferred; some early scholars, such as Ibn Sīrīn in one report, insisted on exact wording", "It is forbidden to everyone", "It is allowed without any condition", "It is required in all cases"], "The majority, including the four imams, allowed narrating by meaning under conditions: the narrator must understand the meaning and the nuances of the language so as not to alter the sense, and it is not for religious formulas such as those of dhikr and adhān. Some scholars, such as Ibn Sīrīn, ʿAbd Allāh ibn ʿUmar in a report, and some of the Ahl al-Ḥadīth, required exact wording. Verbatim narration is preferable."],
    de: ["Was ist die Mehrheitsansicht zur Überlieferung eines Hadith dem Sinn nach (riwāya bi-l-maʿnā) statt im genauen Wortlaut?", ["Sie ist einem Überlieferer erlaubt, der Arabisch und die Bedeutungen kennt und versteht, was den Sinn ändert, wobei wörtliche Überlieferung bevorzugt wird; manche frühe Gelehrte, etwa Ibn Sīrīn nach einem Bericht, bestanden auf dem genauen Wortlaut", "Sie ist allen verboten", "Sie ist ohne jede Bedingung erlaubt", "Sie ist in allen Fällen vorgeschrieben"], "Die Mehrheit, einschließlich der vier Imame, erlaubte die Überlieferung dem Sinn nach unter Bedingungen: Der Überlieferer muss die Bedeutung und die Feinheiten der Sprache verstehen, um den Sinn nicht zu verändern, und es gilt nicht für religiöse Formeln wie die des Ḏikr und des Adhān. Einige Gelehrte wie Ibn Sīrīn, ʿAbd Allāh ibn ʿUmar nach einem Bericht und manche Ahl al-Ḥadīth verlangten den genauen Wortlaut. Die wörtliche Überlieferung ist vorzuziehen."],
    ar: ["ما رأي الجمهور في رواية الحديث بالمعنى لا باللفظ؟", ["تجوز لراوٍ يعرف العربية والمعاني ويدرك ما يغيّر المعنى، والرواية باللفظ أولى، وأصر بعض المتقدمين كابن سيرين في رواية على اللفظ", "تحرم على الجميع", "تجوز بلا قيد", "تجب في كل الأحوال"], "أجاز الجمهور ومنهم الأئمة الأربعة الرواية بالمعنى بشروط: أن يفهم الراوي المعنى ودقائق اللغة حتى لا يغيّر المعنى، ولا تجوز في الأذكار والأذان ونحوها من الألفاظ التعبدية، وأوجب بعضهم كابن سيرين وابن عمر في رواية وبعض أهل الحديث اللفظ، والأولى الرواية باللفظ."] },

  { id: "xhd-016", s: "hadith", g: 4, d: 6, t: ["tahammul", "modes-of-transmission"], src: "Ibn al-Ṣalāḥ, Muqaddima, naw‘ 24–29; al-Khaṭīb al-Baghdādī, al-Kifāya; al-Qāḍī ʿIyāḍ, al-Ilmāʿ",
    en: ["Which list names the eight classical modes of receiving hadith (taḥammul), from the highest to the lowest?", ["Samāʿ (hearing from the teacher), qirāʾa (reading to the teacher), ijāza, munāwala, mukātaba, iʿlām, waṣiyya and wijāda", "Samāʿ, ruʾya, ḥifẓ, kitāba, fahm, ʿamal, ijmāʿ and ikhtiyār", "Samāʿ, qiyās, istiḥsān, ijmāʿ, ʿurf, sadd, masāliḥ and istiṣḥāb", "Ḥifẓ, ruʾya, qirāʾa, tarjama, tafsīr, taʾwīl, istikhrāj and iʿjāz"], "Ibn al-Ṣalāḥ lists eight: samāʿ min lafẓ al-shaykh (the highest for most), qirāʾa ʿalā al-shaykh (ʿarḍ), ijāza (permission), munāwala (handing over), mukātaba (writing), iʿlām (informing), waṣiyya (bequest of a book) and wijāda (finding a writing). The first two are accepted by all; the others differ in force and some are disputed. The order shows the strength of the connection to the teacher."],
    de: ["Welche Liste nennt die acht klassischen Arten des Empfangs von Hadithen (taḥammul), von der höchsten zur niedrigsten?", ["Samāʿ (Hören vom Lehrer), qirāʾa (Vorlesen vor dem Lehrer), iǧāza, munāwala, mukātaba, iʿlām, waṣiyya und wiǧāda", "Samāʿ, ruʾya, ḥifẓ, kitāba, fahm, ʿamal, iǧmāʿ und iḫtiyār", "Samāʿ, qiyās, istiḥsān, iǧmāʿ, ʿurf, sadd, maṣāliḥ und istiṣḥāb", "Ḥifẓ, ruʾya, qirāʾa, tarǧama, tafsīr, taʾwīl, istiḫrāǧ und iʿǧāz"], "Ibn aṣ-Ṣalāḥ nennt acht: samāʿ min lafẓ aš-šaiḫ (für die meisten die höchste), qirāʾa ʿalā š-šaiḫ (ʿarḍ), iǧāza (Erlaubnis), munāwala (Übergabe), mukātaba (Schreiben), iʿlām (Mitteilen), waṣiyya (Vermächtnis eines Buches) und wiǧāda (Auffinden einer Schrift). Die ersten beiden werden von allen akzeptiert; die anderen unterscheiden sich in der Stärke, und manche sind umstritten. Die Reihenfolge zeigt die Stärke der Verbindung zum Lehrer."],
    ar: ["أي قائمة تذكر طرق تحمل الحديث الثمانية الكلاسيكية من الأعلى إلى الأدنى؟", ["السماع من لفظ الشيخ، القراءة عليه (العرض)، الإجازة، المناولة، المكاتبة، الإعلام، الوصية، الوجادة", "السماع، الرؤية، الحفظ، الكتابة، الفهم، العمل، الإجماع، الاختيار", "السماع، القياس، الاستحسان، الإجماع، العرف، السد، المصالح، الاستصحاب", "الحفظ، الرؤية، القراءة، الترجمة، التفسير، التأويل، الاستخراج، الإعجاز"], "عدّ ابن الصلاح ثمانية: سماع لفظ الشيخ (وهو الأعلى عند الأكثر)، وقراءة على الشيخ (العرض)، والإجازة، والمناولة، والمكاتبة، والإعلام، والوصية بالكتاب، والوجادة. والأولان مقبولان باتفاق، والباقي متفاوت القوة وبعضه مختلف فيه، والترتيب يبيّن قوة الصلة بالشيخ."] },

  { id: "xhd-017", s: "hadith", g: 4, d: 6, t: ["takhrij", "types-of-works"], src: "Ibn Ḥajar, Nuzhat al-Naẓar; al-Kattānī, al-Risāla al-Mustaṭrafa; Abū ʿAwāna, al-Mustakhraj ʿalā Ṣaḥīḥ Muslim; al-Ḥākim, al-Mustadrak",
    en: ["Which pair correctly distinguishes a mustakhraj from a mustadrak among the types of hadith books?", ["A mustakhraj re-narrates the hadith of an earlier book with the author’s own chains reaching the same teacher or higher; a mustadrak adds hadith that, in the author’s view, meet the conditions of an earlier book but were omitted", "A mustakhraj collects only fabricated hadith; a mustadrak collects only Quranic verses", "A mustakhraj is an alphabetical index; a mustadrak is a dictionary of narrators", "They are two names for the same type"], "Examples of the mustakhraj are Abū ʿAwāna’s Mustakhraj on Muslim and the Mustakhrajāt of al-Ismāʿīlī on al-Bukhārī. The mustadrak is exemplified by al-Ḥākim’s al-Mustadrak ʿalā al-Ṣaḥīḥayn, which is known for lenient grading, so al-Dhahabī wrote his Talkhīṣ to correct it. The two types are distinguished by whether the author re-narrates or adds."],
    de: ["Welches Paar unterscheidet einen Mustaḫraǧ richtig von einem Mustadrak unter den Arten von Hadithbüchern?", ["Ein Mustaḫraǧ überliefert die Hadithe eines früheren Buches mit eigenen Ketten des Autors neu, die denselben Lehrer oder einen höheren erreichen; ein Mustadrak fügt Hadithe hinzu, die nach Ansicht des Autors die Bedingungen eines früheren Buches erfüllen, aber ausgelassen wurden", "Ein Mustaḫraǧ sammelt nur erfundene Hadithe; ein Mustadrak nur Koranverse", "Ein Mustaḫraǧ ist ein alphabetisches Register; ein Mustadrak ein Überliefererlexikon", "Es sind zwei Namen für dieselbe Art"], "Beispiele des Mustaḫraǧ sind Abū ʿAwānas Mustaḫraǧ zu Muslim und die Mustaḫraǧāt von al-Ismāʿīlī zu al-Buḫārī. Der Mustadrak wird durch al-Ḥākims al-Mustadrak ʿalā ṣ-Ṣaḥīḥain veranschaulicht, der für nachsichtige Bewertung bekannt ist, weshalb adh-Dhahabī sein Talḫīṣ schrieb, um ihn zu korrigieren. Die beiden Arten unterscheiden sich darin, ob der Autor neu überliefert oder hinzufügt."],
    ar: ["أي زوج يفرّق على الوجه الصحيح بين المستخرج والمستدرك من أنواع كتب الحديث؟", ["المستخرج يعيد رواية أحاديث كتاب سابق بأسانيد المؤلف نفسه تلتقي بشيخ الكتاب أو أعلى، والمستدرك يضيف أحاديث رأى المؤلف أنها على شرط الكتاب السابق وفاتته", "المستخرج لا يجمع إلا الموضوعات والمستدرك لا يجمع إلا آيات القرآن", "المستخرج فهرس هجائي والمستدرك معجم للرواة", "هما اسمان لنوع واحد"], "من المستخرجات مستخرج أبي عوانة على مسلم ومستخرجات الإسماعيلي على البخاري، ومن المستدركات «المستدرك على الصحيحين» للحاكم المعروف بتساهله فكتب الذهبي «التلخيص» لتصحيحه، ويفترق النوعان بأن المؤلف في المستخرج يعيد الرواية وفي المستدرك يضيف."] },

  { id: "xhd-018", s: "hadith", g: 4, d: 7, t: ["six-books", "ibn-majah"], src: "Ibn Ṭāhir al-Maqdisī, Shurūṭ al-Aʾimma al-Sitta; Ibn Ḥajar, Tahdhīb al-Tahdhīb, on Ibn Mājah; Ibn al-Athīr, Jāmiʿ al-Uṣūl",
    en: ["Which scholar is credited with adding Sunan Ibn Mājah as the sixth of the canonical books, and what other works were proposed for that place?", ["Abū al-Faḍl ibn Ṭāhir al-Maqdisī (d. 507 AH); al-Muwaṭṭaʾ of Mālik (Razīn) and Sunan al-Dārimī (Ibn Ḥajar) were proposed instead", "Al-Dhahabī; Musnad Aḥmad", "Ibn Ḥajar; the Ṣaḥīḥ of Ibn Khuzayma", "Al-Suyūṭī; Sunan al-Bayhaqī"], "The ‘five books’ (Ṣaḥīḥayn, Abū Dāwūd, al-Tirmidhī, al-Nasāʾī) were widely accepted. Ibn Ṭāhir al-Maqdisī included Ibn Mājah as the sixth. Others, such as Razīn ibn Muʿāwiya, preferred al-Muwaṭṭaʾ, and Ibn al-Athīr put it in place of Ibn Mājah in his Jāmiʿ al-Uṣūl, while later Ibn Ḥajar suggested al-Dārimī. Ibn Mājah contains more weak hadith than the other five."],
    de: ["Welchem Gelehrten wird zugeschrieben, die Sunan Ibn Māǧa als sechstes der kanonischen Bücher hinzugefügt zu haben, und welche anderen Werke wurden für diesen Platz vorgeschlagen?", ["Abū l-Faḍl Ibn Ṭāhir al-Maqdisī (gest. 507 n. H.); stattdessen wurden al-Muwaṭṭaʾ von Mālik (Razīn) und die Sunan ad-Dārimī (Ibn Ḥaǧar) vorgeschlagen", "Aḏ-Ḏahabī; Musnad Aḥmad", "Ibn Ḥaǧar; der Ṣaḥīḥ von Ibn Ḫuzaima", "As-Suyūṭī; Sunan al-Baihaqī"], "Die ‚fünf Bücher‘ (Ṣaḥīḥain, Abū Dāwūd, at-Tirmiḏī, an-Nasāʾī) wurden weithin anerkannt. Ibn Ṭāhir al-Maqdisī nahm Ibn Māǧa als sechstes auf. Andere wie Razīn ibn Muʿāwiya bevorzugten al-Muwaṭṭaʾ, und Ibn al-Aṯīr setzte es in seinem Ǧāmiʿ al-Uṣūl an die Stelle von Ibn Māǧa, während später Ibn Ḥaǧar ad-Dārimī vorschlug. Ibn Māǧa enthält mehr schwache Hadithe als die anderen fünf."],
    ar: ["من الذي يُنسب إليه إضافة سنن ابن ماجه سادسًا في الكتب الستة وما الكتب التي اقتُرحت بدلًا منه؟", ["أبو الفضل ابن طاهر المقدسي (ت 507هـ)، واقتُرح موطأ مالك (رزين) وسنن الدارمي (ابن حجر)", "الذهبي، ومسند أحمد", "ابن حجر، وصحيح ابن خزيمة", "السيوطي، وسنن البيهقي"], "استقر الخمسة الصحيحان وأبو داود والترمذي والنسائي، وأضاف ابن طاهر المقدسي ابن ماجه سادسًا، وفضّل غيره كرزين بن معاوية الموطأ وجعله ابن الأثير في «جامع الأصول» مكان ابن ماجه، واقترح ابن حجر سنن الدارمي، وفي ابن ماجه ضعيف أكثر مما في الخمسة."] },

  { id: "xhd-019", s: "hadith", g: 4, d: 6, t: ["isnad", "golden-chain"], src: "al-Ḥākim, Maʿrifat ʿUlūm al-Ḥadīth; Ibn al-Ṣalāḥ, Muqaddima, naw‘ 1; al-Nawawī, al-Taqrīb",
    en: ["Which chain did al-Bukhārī call the ‘golden chain’ (silsilat al-dhahab), and what is its sense?", ["Mālik from Nāfiʿ from Ibn ʿUmar from the Prophet; it is thought the most reliable chain", "Abū Hurayra from the Prophet directly", "Shuʿba from Qatāda from Anas", "Al-Zuhrī from Sālim from his father"], "Al-Bukhārī (as cited by al-Ḥākim and others) called the chain of Mālik from Nāfiʿ from Ibn ʿUmar the most authentic of chains. The term ‘golden chain’ was also applied by others to other lines, such as al-Shāfiʿī from Mālik from Nāfiʿ from Ibn ʿUmar, but the best-known sense is that attributed to al-Bukhārī."],
    de: ["Welche Kette nannte al-Buḫārī die ‚goldene Kette‘ (silsilat aḏ-ḏahab), und was bedeutet sie?", ["Mālik von Nāfiʿ von Ibn ʿUmar vom Propheten; sie gilt als die zuverlässigste Kette", "Abū Huraira unmittelbar vom Propheten", "Šuʿba von Qatāda von Anas", "Az-Zuhrī von Sālim von seinem Vater"], "Al-Buḫārī (nach al-Ḥākim und anderen) nannte die Kette von Mālik von Nāfiʿ von Ibn ʿUmar die authentischste der Ketten. Der Begriff ‚goldene Kette‘ wurde von anderen auch auf andere Linien angewandt, etwa aš-Šāfiʿī von Mālik von Nāfiʿ von Ibn ʿUmar, doch der bekannteste Sinn ist der al-Buḫārī zugeschriebene."],
    ar: ["أي سلسلة سمّاها البخاري «سلسلة الذهب» وما معناها؟", ["مالك عن نافع عن ابن عمر عن النبي ﷺ، وهي عنده أصح الأسانيد", "أبو هريرة عن النبي ﷺ مباشرة", "شعبة عن قتادة عن أنس", "الزهري عن سالم عن أبيه"], "عدّ البخاري (فيما نقله الحاكم وغيره) سلسلة مالك عن نافع عن ابن عمر أصح الأسانيد، وأطلق غيره لقب سلسلة الذهب على سلاسل أخرى كالشافعي عن مالك عن نافع عن ابن عمر، لكن أشهر معانيها ما نُسب إلى البخاري."] },

  { id: "xhd-020", s: "hadith", g: 4, d: 7, t: ["defects", "mudraj-mudtarib"], src: "Ibn Ḥajar, Nuzhat al-Naẓar; al-Suyūṭī, Tadrīb al-Rāwī; Ibn al-Ṣalāḥ, Muqaddima, naw‘ 20–21",
    en: ["How do the books of terminology define the muḍṭarib and the mudraj hadith?", ["Muḍṭarib: a hadith narrated in contradictory ways of equal strength, so that none can be preferred; mudraj: a hadith in which some words of the narrator or another source have been inserted into the text or chain", "Muḍṭarib: a hadith narrated in anger; mudraj: a hadith about drawing graves", "Muḍṭarib: a hadith with a short chain; mudraj: a hadith with a long chain", "Both are names for forged hadith"], "A hadith is muḍṭarib when its chain or text is narrated differently, with equal force and without possibility of preference or harmonisation; it is weak because it shows poor precision. A mudraj hadith contains an insertion (idrāj), such as a Companion’s or Successor’s explanatory comment mixed into the Prophet’s words, which can be discovered by comparing chains."],
    de: ["Wie definieren die Terminologiebücher den muḍṭarib- und den mudraǧ-Hadith?", ["Muḍṭarib: ein Hadith, der auf widersprüchliche Weise gleich stark überliefert wird, sodass keine bevorzugt werden kann; mudraǧ: ein Hadith, in dessen Text oder Kette Worte des Überlieferers oder einer anderen Quelle eingefügt wurden", "Muḍṭarib: ein im Zorn überlieferter Hadith; mudraǧ: ein Hadith über das Ausheben von Gräbern", "Muḍṭarib: ein Hadith mit kurzer Kette; mudraǧ: ein Hadith mit langer Kette", "Beide sind Namen für erfundene Hadithe"], "Ein Hadith ist muḍṭarib, wenn seine Kette oder sein Text auf unterschiedliche Weise, gleich stark und ohne Möglichkeit der Bevorzugung oder Vereinbarung überliefert wird; er ist schwach, weil er mangelnde Präzision zeigt. Ein mudraǧ-Hadith enthält eine Einfügung (idrāǧ), etwa eine erläuternde Bemerkung eines Gefährten oder Nachfolgers, die in die Worte des Propheten gemischt wurde und durch den Vergleich von Ketten entdeckt werden kann."],
    ar: ["كيف تعرّف كتب المصطلح الحديث المضطرب والمدرج؟", ["المضطرب ما رُوي على أوجه متعارضة متساوية القوة لا يمكن ترجيح أحدها، والمدرج ما أُدخل في متنه أو سنده كلام للراوي أو غيره", "المضطرب ما رُوي في حالة غضب، والمدرج ما يتعلق بحفر القبور", "المضطرب حديث بسند قصير والمدرج حديث بسند طويل", "كلاهما اسم للأحاديث الموضوعة"], "يكون الحديث مضطربًا إذا اختلف في إسناده أو متنه اختلافًا متكافئًا لا يمكن معه الترجيح ولا الجمع، وهو ضعيف لدلالته على قلة الضبط، أما المدرج ففيه زيادة (إدراج) كشرح الصحابي أو التابعي أُدمج في كلام النبي ﷺ ويُكشف بمقارنة الطرق."] },

  { id: "xhd-021", s: "hadith", g: 4, d: 6, t: ["defects", "maqlub-musahhaf"], src: "Ibn Ḥajar, Nuzhat al-Naẓar; Ibn al-Ṣalāḥ, Muqaddima, naw‘ 22 and 23",
    en: ["How are maqlūb and muṣaḥḥaf defined?", ["Maqlūb: a hadith in which a word or narrator is swapped or reversed; muṣaḥḥaf: a hadith changed because the dots or letters of a word are misread", "Maqlūb: a hadith read backwards; muṣaḥḥaf: a hadith written in a book", "Maqlūb: a hadith with a famous author; muṣaḥḥaf: a hadith from the muṣḥaf", "Maqlūb and muṣaḥḥaf are the same"], "A maqlūb hadith has a part reversed, in the text (a word changed with another) or in the chain (the narrator’s name and his father’s name swapped), either by mistake or to test the narrator, as in the famous test of al-Bukhārī in Baghdad. The muṣaḥḥaf (taṣḥīf) is a mistake of reading letters whose shapes are alike, for example by confusing two words differing only in dots."],
    de: ["Wie sind maqlūb und muṣaḥḥaf definiert?", ["Maqlūb: ein Hadith, in dem ein Wort oder ein Überlieferer vertauscht oder umgekehrt wurde; muṣaḥḥaf: ein Hadith, der verändert wurde, weil Punkte oder Buchstaben eines Wortes falsch gelesen wurden", "Maqlūb: ein rückwärts gelesener Hadith; muṣaḥḥaf: ein in einem Buch geschriebener Hadith", "Maqlūb: ein Hadith mit berühmtem Autor; muṣaḥḥaf: ein Hadith aus dem Muṣḥaf", "Maqlūb und muṣaḥḥaf sind dasselbe"], "Ein maqlūb-Hadith hat einen Teil umgekehrt, im Text (ein Wort durch ein anderes ersetzt) oder in der Kette (Name des Überlieferers und seines Vaters vertauscht), entweder aus Versehen oder zur Prüfung des Überlieferers, wie in der berühmten Prüfung al-Buḫārīs in Bagdad. Das Muṣaḥḥaf (taṣḥīf) ist ein Lesefehler bei Buchstaben ähnlicher Gestalt, etwa wenn man zwei nur in den Punkten verschiedene Wörter verwechselt."],
    ar: ["كيف يُعرَّف المقلوب والمصحَّف؟", ["المقلوب حديث أُبدل فيه لفظ أو راوٍ بآخر أو قُلب، والمصحَّف حديث تغيّر بخطأ في قراءة نقط الكلمة أو حروفها", "المقلوب حديث يُقرأ من الآخر، والمصحَّف حديث مكتوب في كتاب", "المقلوب حديث لمؤلف مشهور، والمصحَّف حديث من المصحف", "المقلوب والمصحف شيء واحد"], "المقلوب ما قُلب فيه جزء في المتن (استبدال لفظ بآخر) أو في السند (قلب اسم الراوي واسم أبيه) خطأً أو اختبارًا للراوي كما في اختبار البخاري المشهور في بغداد، والتصحيف خطأ في قراءة حروف متشابهة الشكل كالخلط بين كلمتين تختلفان بالنقط فقط."] },

  { id: "xhd-022", s: "hadith", g: 4, d: 7, t: ["defects", "mazid-fi-muttasil"], src: "Ibn al-Ṣalāḥ, Muqaddima, naw‘ 33 (al-mazīd fī muttaṣil al-asānīd); al-Khaṭīb al-Baghdādī, Tamyīz al-Mazīd fī Muttaṣil al-Asānīd",
    en: ["What is the ‘addition in a connected chain’ (al-mazīd fī muttaṣil al-asānīd)?", ["The mention of an extra narrator in one version of a chain that is elsewhere connected without him, often judged a mistake in the longer version", "An added Companion in the text", "An extra verse in the Quran", "An addition of a commentary by a later scholar"], "In this kind of defect, a narrator inserts a name between two narrators who elsewhere heard from each other directly, as when the chain has a person that others omit, though the contacts are established. Scholars judge, by comparing chains, whether the addition is an error of a narrator (in which case it is rejected) or genuine, as al-Khaṭīb al-Baghdādī showed in Tamyīz al-Mazīd."],
    de: ["Was ist die ‚Hinzufügung in einer verbundenen Kette‘ (al-mazīd fī muttaṣil al-asānīd)?", ["Die Nennung eines zusätzlichen Überlieferers in einer Fassung einer Kette, die anderswo ohne ihn verbunden ist, oft als Irrtum der längeren Fassung beurteilt", "Ein zusätzlicher Gefährte im Text", "Ein zusätzlicher Vers im Koran", "Ein Kommentarzusatz eines späteren Gelehrten"], "Bei dieser Art Mangel fügt ein Überlieferer einen Namen zwischen zwei Überlieferern ein, die anderswo unmittelbar voneinander hörten, etwa wenn die Kette eine Person enthält, die andere auslassen, obwohl die Kontakte feststehen. Die Gelehrten beurteilen durch den Vergleich der Ketten, ob die Hinzufügung ein Irrtum eines Überlieferers ist (dann wird sie verworfen) oder echt, wie al-Ḫaṭīb al-Baġdādī in Tamyīz al-Mazīd zeigte."],
    ar: ["ما «المزيد في متصل الأسانيد»؟", ["ذكر راوٍ زائد في رواية لإسناد جاء في غيرها متصلًا بدونه، وغالبًا يُحكم بوهم في الرواية الأطول", "زيادة صحابي في المتن", "زيادة آية في القرآن", "زيادة تعليق لعالم متأخر"], "في هذا النوع يُدخل بعض الرواة اسمًا بين راويين ثبت سماع أحدهما من الآخر في موضع آخر، ويحكم العلماء بمقارنة الطرق هل الزيادة وهم من الراوي فتُرد أم صحيحة لتعدد اللقاء كما بيّن الخطيب البغدادي في «تمييز المزيد»."] },

  { id: "xhd-023", s: "hadith", g: 4, d: 6, t: ["mukhtalif-al-hadith", "classical-works"], src: "al-Shāfiʿī, Ikhtilāf al-Ḥadīth; Ibn Qutayba, Taʾwīl Mukhtalif al-Ḥadīth; al-Ṭaḥāwī, Sharḥ Mushkil al-Āthār",
    en: ["Which works are classical sources on reconciling apparently conflicting hadith (mukhtalif al-ḥadīth)?", ["al-Shāfiʿī’s Ikhtilāf al-Ḥadīth, Ibn Qutayba’s Taʾwīl Mukhtalif al-Ḥadīth and al-Ṭaḥāwī’s Sharḥ Mushkil al-Āthār", "al-Bukhārī’s al-Adab al-Mufrad", "Muslim’s al-Kunā wa-l-Asmāʾ", "Ibn Mājah’s Tafsīr"], "Mukhtalif al-ḥadīth deals with hadith that seem to conflict, solved by harmonisation (jamʿ), abrogation, preference or suspension, in that order for most scholars. The three works are well-known writings on the topic; the other works named concern etiquette, narrators’ names and tafsīr."],
    de: ["Welche Werke sind klassische Quellen zur Vereinbarung scheinbar widersprüchlicher Hadithe (muḫtalif al-ḥadīth)?", ["Aš-Šāfiʿīs Iḫtilāf al-Ḥadīth, Ibn Qutaibas Taʾwīl Muḫtalif al-Ḥadīth und aṭ-Ṭaḥāwīs Šarḥ Muškil al-Āṯār", "Al-Buḫārīs al-Adab al-Mufrad", "Muslims al-Kunā wa-l-Asmāʾ", "Ibn Māǧas Tafsīr"], "Muḫtalif al-ḥadīth behandelt Hadithe, die einander zu widersprechen scheinen und durch Vereinbarung (ǧamʿ), Aufhebung, Bevorzugung oder Aussetzung gelöst werden, in dieser Reihenfolge nach den meisten Gelehrten. Die drei Werke sind bekannte Schriften zum Thema; die anderen genannten Werke betreffen Anstand, Überlieferernamen und Tafsīr."],
    ar: ["أي كتب مصادر كلاسيكية في التوفيق بين الأحاديث المتعارضة ظاهرًا (مختلف الحديث)؟", ["«اختلاف الحديث» للشافعي و«تأويل مختلف الحديث» لابن قتيبة و«شرح مشكل الآثار» للطحاوي", "«الأدب المفرد» للبخاري", "«الكنى والأسماء» لمسلم", "«التفسير» لابن ماجه"], "يبحث مختلف الحديث في الأحاديث التي يبدو بينها تعارض ويُعالج عند أكثر العلماء بالجمع ثم النسخ ثم الترجيح ثم التوقف، والكتب الثلاثة من أشهر ما كتب فيه، أما الكتب الأخرى فتتعلق بالآداب وأسماء الرواة والتفسير."] },

  { id: "xhd-024", s: "hadith", g: 4, d: 7, t: ["mawduat", "classical-works"], src: "Ibn al-Jawzī, al-Mawḍūʿāt; al-Suyūṭī, al-Laʾāli’ al-Maṣnūʿa fī al-Aḥādīth al-Mawḍūʿa; Ibn Ḥajar, al-Qawl al-Musaddad",
    en: ["What criticism is commonly made of Ibn al-Jawzī’s al-Mawḍūʿāt, and which works responded to it?", ["That it includes hadith that are weak or even sound, not only fabricated; al-Suyūṭī’s al-Laʾāliʾ al-Maṣnūʿa and Ibn Ḥajar’s al-Qawl al-Musaddad examined and corrected it", "That it includes only hadith from Makka", "That it includes no chains", "That it was written before hadith criticism existed"], "Ibn al-Jawzī (d. 597 AH) was severe in judging hadith as fabricated and sometimes classed weak or even reliable hadith as such, and so the scholars checked the book. Al-Suyūṭī’s al-Laʾāliʾ and its additions, and Ibn Ḥajar’s defence of Aḥmad’s Musnad in al-Qawl al-Musaddad, answered many of his judgements. His book remains useful in gathering the material."],
    de: ["Welche Kritik wird häufig an Ibn al-Ǧauzīs al-Mauḍūʿāt geübt, und welche Werke antworteten darauf?", ["Dass es auch schwache oder gar gesunde Hadithe aufnimmt, nicht nur erfundene; as-Suyūṭīs al-Laʾāliʾ al-Maṣnūʿa und Ibn Ḥaǧars al-Qaul al-Musaddad prüften und korrigierten es", "Dass es nur Hadithe aus Mekka enthält", "Dass es keine Ketten enthält", "Dass es geschrieben wurde, bevor es Hadithkritik gab"], "Ibn al-Ǧauzī (gest. 597 n. H.) war streng im Urteil, Hadithe seien erfunden, und stufte mitunter schwache oder gar zuverlässige so ein, weshalb die Gelehrten das Buch nachprüften. As-Suyūṭīs al-Laʾāliʾ samt Ergänzungen und Ibn Ḥaǧars Verteidigung von Aḥmads Musnad in al-Qaul al-Musaddad beantworteten viele seiner Urteile. Sein Buch bleibt nützlich, um das Material zusammenzutragen."],
    ar: ["ما الانتقاد الشائع على «الموضوعات» لابن الجوزي وأي كتب ردّت عليه؟", ["أنه أدخل أحاديث ضعيفة بل وصحيحة لا موضوعة فقط، وفحصه وصحّحه «اللآلئ المصنوعة» للسيوطي و«القول المسدد» لابن حجر", "أنه لم يذكر إلا أحاديث مكة", "أنه خلا من الأسانيد", "أنه ألّف قبل وجود النقد الحديثي"], "تشدد ابن الجوزي (ت 597هـ) في الحكم بالوضع وأدخل أحيانًا ضعيفًا أو صحيحًا في الموضوع، فتعقبه العلماء، وأجاب عن كثير من أحكامه «اللآلئ المصنوعة» وزياداتها للسيوطي ودفاع ابن حجر عن مسند أحمد في «القول المسدد»، ويبقى كتابه نافعًا في جمع المادة."] },

  { id: "xhd-025", s: "hadith", g: 4, d: 6, t: ["mawduat", "fabricators"], src: "Ibn al-Ṣalāḥ, Muqaddima, naw‘ 21 (al-mawḍūʿ); Ibn Ḥibbān, al-Majrūḥīn; al-Suyūṭī, Tadrīb al-Rāwī",
    en: ["Why did some pious people fabricate hadith in the virtues of Quranic sūras, and how did the scholars respond?", ["They believed they were encouraging people to read the Quran, but the scholars declared the practice forbidden and fabrications false, identifying narrators such as Abū ʿIṣma Nūḥ ibn Abī Maryam who admitted it", "They fabricated them under orders of caliphs, and the scholars accepted them", "They were fabricated by orientalists only", "The scholars accepted all of them as reliable"], "Ibn al-Ṣalāḥ and others mention that some ascetics fabricated hadith to encourage devotion; Nūḥ ibn Abī Maryam is reported to have acknowledged that he made up hadith in the virtues of the Quran’s sūras, attributing them to Ibn ʿAbbās, to turn people to the Quran. The scholars denounced this on the basis of the Prophet’s warning against lying about him, and said that no good purpose justifies it."],
    de: ["Warum erfanden manche Fromme Hadithe über die Vorzüge von Koransuren, und wie reagierten die Gelehrten?", ["Sie glaubten, die Menschen zum Koranlesen zu ermuntern, doch die Gelehrten erklärten die Praxis für verboten und die Erfindungen für falsch und identifizierten Überlieferer wie Abū ʿIṣma Nūḥ ibn Abī Maryam, die es zugaben", "Sie erfanden sie auf Befehl von Kalifen, und die Gelehrten nahmen sie an", "Sie wurden nur von Orientalisten erfunden", "Die Gelehrten nahmen alle als zuverlässig an"], "Ibn aṣ-Ṣalāḥ und andere erwähnen, dass manche Asketen Hadithe erfanden, um die Frömmigkeit zu fördern; von Nūḥ ibn Abī Maryam wird berichtet, er habe zugegeben, Hadithe über die Vorzüge der Koransuren erfunden und Ibn ʿAbbās zugeschrieben zu haben, um die Menschen dem Koran zuzuwenden. Die Gelehrten verurteilten das auf Grundlage der Warnung des Propheten vor Lüge über ihn und sagten, kein guter Zweck rechtfertige es."],
    ar: ["لماذا وضع بعض الصالحين أحاديث في فضائل سور القرآن وكيف ردّ العلماء؟", ["ظنوا أنهم يرغّبون الناس في القرآن، فحرّم العلماء ذلك وبيّنوا بطلان الموضوعات وعيّنوا رواة كأبي عصمة نوح بن أبي مريم الذي أقرّ بذلك", "وضعوها بأمر الخلفاء وقبلها العلماء", "وضعها المستشرقون وحدهم", "قبلها العلماء كلها صحيحة"], "ذكر ابن الصلاح وغيره أن بعض الزهاد وضعوا أحاديث للترغيب، ويُروى أن نوح بن أبي مريم اعترف بوضع أحاديث في فضائل سور القرآن ونسبها إلى ابن عباس ليصرف الناس إلى القرآن، وأنكر العلماء ذلك لتحذير النبي ﷺ من الكذب عليه ولأنه لا يبرره غرض حسن."] },

  { id: "xhd-026", s: "hadith", g: 4, d: 6, t: ["isnad", "sanad-importance"], src: "Muslim, Ṣaḥīḥ, introduction (muqaddima); Ibn Ḥibbān, al-Majrūḥīn; al-Khaṭīb al-Baghdādī, Sharaf Aṣḥāb al-Ḥadīth",
    en: ["According to Muslim’s introduction, when did the practice of demanding the chain become common, and who is quoted?", ["After the strife (fitna), when it became important to ask for the names of the narrators; Ibn Sīrīn is quoted as saying they had not asked about the chain before that", "In the time of the Prophet, who demanded chains", "Only in the 5th century AH", "In the time of al-Bukhārī, who invented it"], "In the introduction to the Ṣaḥīḥ, Muslim reports from Ibn Sīrīn that the people had not asked about the chain, but when the fitna occurred they said ‘name us your men’, so that the sunna of the Ahl al-Sunna is accepted and that of the Ahl al-Bidʿa rejected. Ibn al-Mubārak is also quoted that the chain is part of the religion and without it anyone could say what he wished."],
    de: ["Wann wurde nach Muslims Einleitung das Verlangen nach der Kette üblich, und wer wird zitiert?", ["Nach der Zwietracht (fitna), als es wichtig wurde, nach den Namen der Überlieferer zu fragen; Ibn Sīrīn wird mit der Aussage zitiert, man habe vorher nicht nach der Kette gefragt", "Zur Zeit des Propheten, der Ketten verlangte", "Erst im 5. Jh. n. H.", "Zur Zeit al-Buḫārīs, der es erfand"], "In der Einleitung zum Ṣaḥīḥ berichtet Muslim von Ibn Sīrīn, die Leute hätten früher nicht nach der Kette gefragt, aber als die Fitna geschah, hätten sie gesagt ‚nennt uns eure Männer‘, damit die Sunna der Ahl as-Sunna angenommen und die der Ahl al-Bidʿa verworfen werde. Auch Ibn al-Mubārak wird zitiert, die Kette gehöre zur Religion, und ohne sie könne jeder sagen, was er wolle."],
    ar: ["بحسب مقدمة مسلم، متى شاع طلب الإسناد ومن الذي يُنقل عنه ذلك؟", ["بعد الفتنة حين صار لازمًا السؤال عن أسماء الرواة، ويُنقل عن ابن سيرين أنهم لم يكونوا يسألون عن الإسناد قبل ذلك", "في عهد النبي ﷺ الذي طلب الأسانيد", "في القرن الخامس الهجري فقط", "في عهد البخاري الذي ابتدعه"], "روى مسلم في مقدمة صحيحه عن ابن سيرين أنهم لم يكونوا يسألون عن الإسناد فلما وقعت الفتنة قالوا سمّوا لنا رجالكم فيُنظر إلى أهل السنة فتؤخذ سنتهم وإلى أهل البدع فلا يؤخذ حديثهم، ويُروى عن ابن المبارك أن الإسناد من الدين ولولاه لقال من شاء ما شاء."] },

  { id: "xhd-027", s: "hadith", g: 4, d: 6, t: ["classical-works", "taqrib"], src: "Ibn Ḥajar, Nuzhat al-Naẓar; Ibn Ḥajar, Nukhbat al-Fikar; al-ʿIrāqī, al-Alfiyya fī ʿUlūm al-Ḥadīth",
    en: ["Which statement correctly matches works of hadith terminology with their authors?", ["Ibn al-Ṣalāḥ: Muqaddima; al-ʿIrāqī: Alfiyya; Ibn Ḥajar: Nukhbat al-Fikar", "Ibn al-Ṣalāḥ: Nukhba; al-ʿIrāqī: Muqaddima; Ibn Ḥajar: Alfiyya", "Ibn al-Ṣalāḥ: Alfiyya; al-ʿIrāqī: Nukhba; Ibn Ḥajar: Muqaddima", "All three are titles by al-Bukhārī"], "The Muqaddima of Ibn al-Ṣalāḥ (the first systematic textbook) was versified by al-ʿIrāqī in his Alfiyya and abridged in other works. Ibn Ḥajar’s Nukhbat al-Fikar is a concise work with its own commentary Nuzhat al-Naẓar. These three form the core of the study of muṣṭalaḥ al-ḥadīth."],
    de: ["Welche Aussage ordnet Werke der Hadith-Terminologie ihren Autoren richtig zu?", ["Ibn aṣ-Ṣalāḥ: Muqaddima; al-ʿIrāqī: Alfiyya; Ibn Ḥaǧar: Nuḫbat al-Fikar", "Ibn aṣ-Ṣalāḥ: Nuḫba; al-ʿIrāqī: Muqaddima; Ibn Ḥaǧar: Alfiyya", "Ibn aṣ-Ṣalāḥ: Alfiyya; al-ʿIrāqī: Nuḫba; Ibn Ḥaǧar: Muqaddima", "Alle drei sind Titel von al-Buḫārī"], "Die Muqaddima von Ibn aṣ-Ṣalāḥ (das erste systematische Lehrbuch) wurde von al-ʿIrāqī in seiner Alfiyya in Verse gefasst und in anderen Werken gekürzt. Ibn Ḥaǧars Nuḫbat al-Fikar ist ein knappes Werk mit eigenem Kommentar Nuzhat an-Naẓar. Diese drei bilden den Kern des Studiums von Muṣṭalaḥ al-Ḥadīth."],
    ar: ["أي عبارة تقرن كتب مصطلح الحديث بمؤلفيها على الوجه الصحيح؟", ["ابن الصلاح: المقدمة؛ العراقي: الألفية؛ ابن حجر: نخبة الفكر", "ابن الصلاح: النخبة؛ العراقي: المقدمة؛ ابن حجر: الألفية", "ابن الصلاح: الألفية؛ العراقي: النخبة؛ ابن حجر: المقدمة", "الثلاثة عناوين للبخاري"], "نظم العراقي «مقدمة» ابن الصلاح وهي أول كتاب منهجي في الفن في «ألفيته»، واختُصرت في أعمال أخرى، و«نخبة الفكر» لابن حجر متن موجز له شرحه «نزهة النظر»، وهذه الثلاثة أساس دراسة مصطلح الحديث."] },

  { id: "xhd-028", s: "hadith", g: 4, d: 7, t: ["muallaq", "bukhari-works"], src: "Ibn Ḥajar, Taghlīq al-Taʿlīq ʿalā Ṣaḥīḥ al-Bukhārī; Ibn Ḥajar, Hady al-Sārī, introduction",
    en: ["What are the muʿallaqāt in al-Bukhārī’s Ṣaḥīḥ, and who traced their chains?", ["Hadith cited with the chain cut at the beginning, which Ibn Ḥajar traced in Taghlīq al-Taʿlīq", "Hadith that al-Bukhārī rejected", "Hadith narrated by women only", "Hadith with a gap at the end of the chain"], "In places al-Bukhārī gives a hadith or a report from the beginning of the chain missing (taʿlīq). Some are in the firm form (‘he said’), which are generally authentic, and some in the doubtful form (‘it was said’). Ibn Ḥajar compiled their chains from other books in Taghlīq al-Taʿlīq. The muʿallaqāt do not count as hadith of the strict conditions of the Ṣaḥīḥ in themselves."],
    de: ["Was sind die Muʿallaqāt in al-Buḫārīs Ṣaḥīḥ, und wer verfolgte ihre Ketten?", ["Hadithe, die mit am Anfang abgeschnittener Kette zitiert werden und deren Ketten Ibn Ḥaǧar in Taġlīq at-Taʿlīq verfolgte", "Hadithe, die al-Buḫārī verwarf", "Hadithe, die nur von Frauen überliefert wurden", "Hadithe mit einer Lücke am Ende der Kette"], "An manchen Stellen gibt al-Buḫārī einen Hadith oder Bericht mit fehlendem Kettenanfang (taʿlīq). Einige stehen in der festen Form (‚er sagte‘), die im Allgemeinen authentisch sind, und einige in der unsicheren Form (‚es wurde gesagt‘). Ibn Ḥaǧar stellte ihre Ketten aus anderen Büchern in Taġlīq at-Taʿlīq zusammen. Die Muʿallaqāt zählen an sich nicht als Hadithe mit den strengen Bedingungen des Ṣaḥīḥ."],
    ar: ["ما المعلقات في صحيح البخاري ومن الذي وصل أسانيدها؟", ["أحاديث ذُكرت بحذف مبدأ الإسناد وقد وصل أسانيدها ابن حجر في «تغليق التعليق»", "أحاديث ردّها البخاري", "أحاديث رواها النساء وحدهن", "أحاديث في آخر سندها سقط"], "يورد البخاري في مواضع حديثًا أو أثرًا محذوف أول سنده (تعليقًا)، وبعضها بصيغة الجزم (قال) وهي في الغالب صحيحة وبعضها بصيغة التمريض (يُروى) وقد وصل ابن حجر أسانيدها من كتب أخرى في «تغليق التعليق»، والمعلقات لا تدخل في شرط الصحيح الصارم لذاتها."] },

  { id: "xhd-029", s: "hadith", g: 4, d: 6, t: ["hasan", "li-ghayrihi"], src: "Ibn Ḥajar, Nuzhat al-Naẓar; al-Nawawī, al-Taqrīb; Ibn al-Ṣalāḥ, Muqaddima, naw‘ 2",
    en: ["What is ḥasan li-ghayrihi, and how does it arise?", ["A weak hadith whose weakness is light, raised to ḥasan by corroborating chains or witnesses", "A sound hadith whose chain is long", "A fabricated hadith that is repeated by many", "A hadith of a Companion about the Prophet’s dress"], "A hadith that is slightly weak, for example through a narrator with poor memory, can be strengthened by other chains of similar or better strength, so it rises to ḥasan li-ghayrihi. This does not apply to hadith with severe weakness, such as fabrication or the narrator’s known lying. The scholars therefore speak of ‘weak with an excusable weakness’ and ‘weak with an inexcusable weakness’."],
    de: ["Was ist ḥasan li-ġairihi, und wie entsteht es?", ["Ein schwacher Hadith mit leichter Schwäche, der durch bestätigende Ketten oder Zeugen zu ḥasan erhoben wird", "Ein gesunder Hadith mit langer Kette", "Ein erfundener Hadith, der von vielen wiederholt wird", "Ein Hadith eines Gefährten über die Kleidung des Propheten"], "Ein leicht schwacher Hadith, etwa durch einen Überlieferer mit schlechtem Gedächtnis, kann durch andere Ketten von ähnlicher oder besserer Stärke gestärkt werden, sodass er zu ḥasan li-ġairihi aufsteigt. Das gilt nicht für Hadithe mit schwerer Schwäche wie Erfindung oder bekannter Lüge des Überlieferers. Die Gelehrten sprechen deshalb von ‚schwach mit verzeihlicher Schwäche‘ und ‚schwach mit unverzeihlicher Schwäche‘."],
    ar: ["ما الحسن لغيره وكيف ينشأ؟", ["حديث ضعفه خفيف ارتقى إلى الحسن بتعدد الطرق أو الشواهد", "حديث صحيح طويل السند", "حديث موضوع كثر رواته", "حديث صحابي عن لباس النبي ﷺ"], "إذا كان الحديث ضعيفًا ضعفًا يسيرًا كأن يكون في راويه سوء حفظ، ورُوي من طرق أخرى مثله أو أقوى، ارتقى إلى الحسن لغيره، ولا ينطبق ذلك على الضعف الشديد كالوضع أو تعمد الراوي الكذب، ولذلك يفرّق العلماء بين ضعف يُجبر وضعف لا يُجبر."] },

  { id: "xhd-030", s: "hadith", g: 4, d: 7, t: ["acceptance", "dhaif-in-fada-il"], tr: ["comparative"], src: "Ibn Ḥajar, al-Qawl al-Badīʿ; al-Nawawī, al-Adhkār, introduction; al-Suyūṭī, Tadrīb al-Rāwī",
    en: ["What are the conditions that Ibn Ḥajar attributes to scholars who allow acting on weak hadith in virtuous deeds (faḍāʾil al-aʿmāl)?", ["That the weakness is not severe, that the deed falls under an established general principle, and that one does not believe the hadith itself is established", "That the hadith be fabricated but useful", "That the hadith be about the law of inheritance", "That the chain be mutawātir"], "Ibn Ḥajar, reporting from al-ʿAlāʾī and others, gives three conditions for those who allow weak hadith in faḍāʾil: the weakness must not be severe, the content must be under a recognised principle, and one should not believe it is established from the Prophet. Some scholars, like Ibn al-ʿArabī and others, rejected acting on weak hadith altogether, so the topic is disputed."],
    de: ["Welche Bedingungen schreibt Ibn Ḥaǧar den Gelehrten zu, die das Handeln nach schwachen Hadithen bei tugendhaften Taten (faḍāʾil al-aʿmāl) erlauben?", ["Dass die Schwäche nicht schwer ist, dass die Tat unter einen gesicherten allgemeinen Grundsatz fällt und dass man nicht glaubt, der Hadith selbst sei gesichert", "Dass der Hadith erfunden, aber nützlich ist", "Dass der Hadith das Erbrecht betrifft", "Dass die Kette mutawātir ist"], "Ibn Ḥaǧar nennt, von al-ʿAlāʾī und anderen berichtend, drei Bedingungen für diejenigen, die schwache Hadithe bei Faḍāʾil erlauben: Die Schwäche darf nicht schwer sein, der Inhalt muss unter einem anerkannten Grundsatz stehen, und man soll nicht glauben, er sei vom Propheten gesichert. Manche Gelehrte, etwa Ibn al-ʿArabī und andere, lehnten das Handeln nach schwachen Hadithen ganz ab, das Thema ist daher umstritten."],
    ar: ["ما الشروط التي ينسبها ابن حجر إلى من يجيز العمل بالضعيف في فضائل الأعمال؟", ["ألا يكون الضعف شديدًا، وأن يندرج العمل تحت أصل عام ثابت، وألا يعتقد ثبوت الحديث نفسه", "أن يكون الحديث موضوعًا نافعًا", "أن يكون في أحكام الميراث", "أن يكون السند متواترًا"], "ينقل ابن حجر عن العلائي وغيره ثلاثة شروط لمن أجاز العمل بالضعيف في الفضائل: ألا يشتد ضعفه، وأن يدخل تحت أصل معمول به، وألا يعتقد ثبوته عن النبي ﷺ، ومنع بعض العلماء كابن العربي العمل بالضعيف مطلقًا فالمسألة خلافية."] },

  { id: "xhd-031", s: "hadith", g: 4, d: 6, t: ["tabaqat", "successors"], src: "Ibn Ḥajar, Taqrīb al-Tahdhīb, introduction; Ibn Ḥajar, Nuzhat al-Naẓar; Ibn al-Ṣalāḥ, Muqaddima, naw‘ 39–40",
    en: ["What is a mukhaḍram narrator in hadith terminology?", ["One who lived in both the pre-Islamic period and the time of the Prophet and accepted Islam, but did not see him, so he is counted among the Successors", "A narrator who lived only among the Companions", "A narrator who was a woman", "A narrator who narrated from a jinn"], "A mukhaḍram (plural mukhaḍramūn) is someone who reached the time of Jāhiliyya and the time of the Prophet ﷺ, and became Muslim in his lifetime but never met him. The scholars count such people among the senior Successors. They are distinguished from Companions by the lack of meeting, as the Companion is defined as one who met the Prophet ﷺ as a believer and died as one."],
    de: ["Was ist ein muḫaḍram-Überlieferer in der Hadith-Terminologie?", ["Einer, der sowohl in vorislamischer Zeit als auch zur Zeit des Propheten lebte und den Islam annahm, ihn aber nicht sah, sodass er zu den Nachfolgern gezählt wird", "Ein Überlieferer, der nur unter den Gefährten lebte", "Ein Überlieferer, der eine Frau war", "Ein Überlieferer, der von einem Ǧinn überlieferte"], "Ein Muḫaḍram (Plural muḫaḍramūn) ist jemand, der die Zeit der Ǧāhiliyya und die Zeit des Propheten ﷺ erreichte und zu dessen Lebzeiten Muslim wurde, ihm aber nie begegnete. Die Gelehrten zählen solche Leute zu den älteren Nachfolgern. Von den Gefährten unterscheiden sie sich durch das Fehlen der Begegnung, da der Gefährte als jemand definiert ist, der den Propheten ﷺ als Gläubiger traf und als solcher starb."],
    ar: ["ما المخضرم في اصطلاح المحدثين؟", ["من أدرك الجاهلية وزمن النبي ﷺ وأسلم ولم يره، فيُعدّ من التابعين", "راوٍ عاش بين الصحابة فقط", "راوٍ كان امرأة", "راوٍ روى عن جني"], "المخضرم من أدرك الجاهلية وحياة النبي ﷺ وأسلم في حياته ولم يلقه، ويعدّه العلماء من كبار التابعين، ويفترق عن الصحابي بعدم اللقاء إذ الصحابي من لقي النبي ﷺ مؤمنًا به ومات على ذلك."] },

  { id: "xhd-032", s: "hadith", g: 4, d: 7, t: ["companion-definition", "disagreement"], tr: ["comparative"], src: "Ibn Ḥajar, al-Iṣāba, introduction; Ibn al-Ṣalāḥ, Muqaddima, naw‘ 39; al-Bukhārī, Ṣaḥīḥ, Kitāb faḍāʾil aṣḥāb al-nabī (opening)",
    en: ["How do the scholars differ in defining a Companion (ṣaḥābī)?", ["Most hadith scholars, with al-Bukhārī and Aḥmad, count anyone who met the Prophet ﷺ as a believer and died Muslim; some, such as Saʿīd ibn al-Musayyab in one report, required a year or a battle with him", "All scholars required ten years of companionship", "All scholars required only to have lived in his time", "All scholars required narrating at least ten hadith"], "The majority definition, from al-Bukhārī and Ibn Ḥajar, is broad: whoever saw or met the Prophet ﷺ as a believer and died in Islam. The narrower view, attributed to Saʿīd ibn al-Musayyab and followed by some Uṣūlīs, asks for lengthy companionship, for example a year or participation in a campaign. The wider view prevailed in hadith because of the honour of seeing him ﷺ."],
    de: ["Wie unterscheiden sich die Gelehrten in der Definition eines Gefährten (ṣaḥābī)?", ["Die meisten Hadithgelehrten, mit al-Buḫārī und Aḥmad, zählen jeden, der den Propheten ﷺ als Gläubiger traf und als Muslim starb; manche, etwa Saʿīd ibn al-Musayyab nach einem Bericht, verlangten ein Jahr oder einen Feldzug mit ihm", "Alle Gelehrten verlangten zehn Jahre Gefährtenschaft", "Alle Gelehrten verlangten nur, zu seiner Zeit gelebt zu haben", "Alle Gelehrten verlangten die Überlieferung von mindestens zehn Hadithen"], "Die Mehrheitsdefinition von al-Buḫārī und Ibn Ḥaǧar ist weit: wer den Propheten ﷺ als Gläubiger sah oder traf und im Islam starb. Die engere Ansicht, Saʿīd ibn al-Musayyab zugeschrieben und von manchen Uṣūlīs übernommen, verlangt längere Gefährtenschaft, etwa ein Jahr oder Teilnahme an einem Feldzug. Die weitere Ansicht setzte sich im Hadith durch wegen der Ehre, ihn ﷺ gesehen zu haben."],
    ar: ["كيف يختلف العلماء في تعريف الصحابي؟", ["جمهور المحدثين ومنهم البخاري وأحمد يعدّون كل من لقي النبي ﷺ مؤمنًا ومات مسلمًا، واشترط بعضهم كابن المسيب في رواية صحبة سنة أو غزوة", "اشترط كل العلماء عشر سنين من الصحبة", "اكتفى كل العلماء بالعيش في زمنه", "اشترط كل العلماء رواية عشرة أحاديث"], "التعريف المشهور عند البخاري وابن حجر واسع: من رأى النبي ﷺ أو لقيه مؤمنًا به ومات على الإسلام، والقول الأضيق المنسوب إلى سعيد بن المسيب وبعض الأصوليين يطلب طول الصحبة كسنة أو غزوة، وغلب الأول عند المحدثين لشرف رؤيته ﷺ."] },

  { id: "xhd-033", s: "hadith", g: 4, d: 7, t: ["mukthirun", "companions-narrators"], src: "Ibn al-Jawzī, Talqīḥ Fuhūm Ahl al-Athar; al-Dhahabī, Siyar Aʿlām al-Nubalāʾ; Ibn Ḥazm, Asmāʾ al-Ṣaḥāba al-Ruwāt",
    en: ["Who are the Companions known as ‘al-muksirūn’ (those who narrated over 1,000 hadith) in the classical lists?", ["Abū Hurayra, ʿAbd Allāh ibn ʿUmar, Anas ibn Mālik, ʿĀʾisha, ʿAbd Allāh ibn ʿAbbās and Jābir ibn ʿAbd Allāh, with Abū Saʿīd al-Khudrī usually added", "Abū Bakr, ʿUmar, ʿUthmān and ʿAlī only", "Khālid ibn al-Walīd, Saʿd ibn Abī Waqqāṣ and Bilāl", "Only the women among the Companions"], "Lists of the muksirūn (those who narrated many hadith) include Abū Hurayra, who is first by far, then Ibn ʿUmar, Anas, ʿĀʾisha, Ibn ʿAbbās and Jābir; Abū Saʿīd al-Khudrī is also usually included though his numbers are a little lower. The exact counts differ between lists depending on how repeated chains are counted, so scholars speak in approximate numbers."],
    de: ["Wer sind die Gefährten, die in den klassischen Listen als ‚al-muksirūn‘ (mit über 1000 Hadithen) bekannt sind?", ["Abū Huraira, ʿAbd Allāh ibn ʿUmar, Anas ibn Mālik, ʿĀʾiša, ʿAbd Allāh ibn ʿAbbās und Ǧābir ibn ʿAbd Allāh, meist ergänzt um Abū Saʿīd al-Ḫudrī", "Nur Abū Bakr, ʿUmar, ʿUṯmān und ʿAlī", "Ḫālid ibn al-Walīd, Saʿd ibn Abī Waqqāṣ und Bilāl", "Nur die Frauen unter den Gefährten"], "Listen der Muksirūn (derer, die viele Hadithe überlieferten) umfassen Abū Huraira, der mit großem Abstand an erster Stelle steht, dann Ibn ʿUmar, Anas, ʿĀʾiša, Ibn ʿAbbās und Ǧābir; auch Abū Saʿīd al-Ḫudrī wird meist aufgenommen, obwohl seine Zahlen etwas niedriger sind. Die genauen Zahlen unterscheiden sich je nach Liste, je nachdem, wie wiederholte Ketten gezählt werden, weshalb die Gelehrten ungefähre Zahlen nennen."],
    ar: ["من الصحابة المعروفون بـ«المكثرين» (من رووا أكثر من ألف حديث) في القوائم الكلاسيكية؟", ["أبو هريرة وعبد الله بن عمر وأنس بن مالك وعائشة وعبد الله بن عباس وجابر بن عبد الله، ويُضاف عادة أبو سعيد الخدري", "أبو بكر وعمر وعثمان وعلي فقط", "خالد بن الوليد وسعد بن أبي وقاص وبلال", "النساء من الصحابة فقط"], "تشمل قوائم المكثرين أبا هريرة وهو الأول بفارق كبير ثم ابن عمر وأنسًا وعائشة وابن عباس وجابرًا، ويُضاف عادة أبو سعيد الخدري وإن قلّ عدده قليلًا، وتختلف الأعداد بحسب طريقة عدّ الطرق المكررة فيذكرها العلماء تقريبًا."] },

  { id: "xhd-034", s: "hadith", g: 4, d: 6, t: ["fuqaha-companions", "ibn-abbas"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ; Ibn Ḥajar, al-Iṣāba; al-Bukhārī, Ṣaḥīḥ, Kitāb al-ʿilm (Ibn ʿAbbās)",
    en: ["Why is ʿAbd Allāh ibn ʿAbbās called ‘ḥabr al-umma’ and ‘tarjumān al-Qurʾān’?", ["Because of his deep knowledge of the Quran’s interpretation, following the Prophet’s prayer for him to be given understanding of the religion", "Because he was the first caliph", "Because he led the first conquests", "Because he compiled the first Muṣḥaf"], "Ibn ʿAbbās (d. c. 68 AH) was a young cousin of the Prophet ﷺ, and reports record the Prophet’s supplication that he be given understanding in the religion and knowledge of interpretation. Companions like ʿUmar consulted him despite his youth. He is the main source of the Makkan school of tafsīr through students such as Mujāhid, ʿIkrima and Saʿīd ibn Jubayr."],
    de: ["Warum wird ʿAbd Allāh ibn ʿAbbās ‚ḥabr al-umma‘ und ‚tarǧumān al-Qurʾān‘ genannt?", ["Wegen seines tiefen Wissens in der Auslegung des Korans, im Anschluss an das Gebet des Propheten, ihm Verständnis der Religion zu geben", "Weil er der erste Kalif war", "Weil er die ersten Eroberungen anführte", "Weil er den ersten Muṣḥaf zusammenstellte"], "Ibn ʿAbbās (gest. um 68 n. H.) war ein junger Vetter des Propheten ﷺ, und Berichte halten das Bittgebet des Propheten fest, ihm Verständnis der Religion und Wissen der Auslegung zu geben. Gefährten wie ʿUmar befragten ihn trotz seiner Jugend. Er ist die Hauptquelle der mekkanischen Tafsīr-Schule durch Schüler wie Muǧāhid, ʿIkrima und Saʿīd ibn Ǧubair."],
    ar: ["لماذا يُلقَّب عبد الله بن عباس «حبر الأمة» و«ترجمان القرآن»؟", ["لعمق علمه بتفسير القرآن إثر دعاء النبي ﷺ له بالفقه في الدين", "لأنه أول الخلفاء", "لأنه قاد أولى الفتوح", "لأنه جمع أول مصحف"], "كان ابن عباس (ت نحو 68هـ) ابن عم النبي ﷺ وهو صغير، وتروي الأخبار دعاءه له بالفقه في الدين وعلم التأويل، وكان كبار الصحابة كعمر يستشيرونه رغم حداثة سنه، وهو أصل مدرسة التفسير المكية عبر تلاميذه كمجاهد وعكرمة وسعيد بن جبير."] },

  { id: "xhd-035", s: "hadith", g: 4, d: 7, t: ["musnad-ahmad", "classical-works"], src: "Ibn Ḥajar, al-Qawl al-Musaddad fī al-Dhabb ʿan Musnad al-Imām Aḥmad; al-Dhahabī, Siyar; Ibn al-Jawzī, Khaṣāʾiṣ Musnad Aḥmad",
    en: ["How do hadith scholars generally regard the status of Musnad Aḥmad with respect to authenticity?", ["It contains sound, good and some weak hadith, and a few that scholars described as fabricated, though Ibn Ḥajar defended it against the claim that it includes many fabrications", "It contains only sound hadith, like the Ṣaḥīḥayn", "It contains only fabricated hadith", "It contains only hadith of the Ahl al-Bayt"], "Musnad Aḥmad is arranged by Companion and is very large. Aḥmad did not claim that all were sound; the scholars assess it as containing the whole range. Ibn al-Jawzī listed some hadith in it as fabricated, and Ibn Ḥajar in al-Qawl al-Musaddad defended the Musnad, accepting a small number as fabricated. The Musnad is nonetheless a major source."],
    de: ["Wie beurteilen Hadithgelehrte den Status von Musnad Aḥmad hinsichtlich der Authentizität im Allgemeinen?", ["Er enthält gesunde, gute und einige schwache Hadithe sowie wenige, die Gelehrte als erfunden bezeichneten, wobei Ibn Ḥaǧar ihn gegen die Behauptung verteidigte, er enthalte viele Erfindungen", "Er enthält nur gesunde Hadithe wie die Ṣaḥīḥain", "Er enthält nur erfundene Hadithe", "Er enthält nur Hadithe der Ahl al-Bait"], "Musnad Aḥmad ist nach Gefährten geordnet und sehr umfangreich. Aḥmad behauptete nicht, alles sei gesund; die Gelehrten beurteilen ihn als das ganze Spektrum enthaltend. Ibn al-Ǧauzī führte einige Hadithe darin als erfunden auf, und Ibn Ḥaǧar verteidigte den Musnad in al-Qaul al-Musaddad und räumte eine kleine Zahl als erfunden ein. Der Musnad bleibt dennoch eine Hauptquelle."],
    ar: ["كيف ينظر المحدثون عمومًا إلى مرتبة «مسند أحمد» من حيث الصحة؟", ["فيه الصحيح والحسن وبعض الضعيف وأحاديث قليلة وصفها العلماء بالوضع، ودافع ابن حجر عنه ضد دعوى كثرة الموضوعات", "فيه الصحيح فقط كالصحيحين", "فيه الموضوع فقط", "فيه أحاديث أهل البيت فقط"], "المسند مرتب على الصحابة وهو ضخم جدًّا، ولم يدّع أحمد أن كله صحيح بل فيه الدرجات كلها، وأدرج ابن الجوزي بعض أحاديثه في الموضوعات، ودافع ابن حجر عن المسند في «القول المسدد» وأقرّ بعدد قليل منها، ويبقى المسند مصدرًا مهمًّا."] },

  { id: "xhd-036", s: "hadith", g: 4, d: 6, t: ["bukhari-muslim", "ranking"], src: "al-Nawawī, Sharḥ Ṣaḥīḥ Muslim, introduction; Ibn Ḥajar, Hady al-Sārī; Ibn al-Ṣalāḥ, Muqaddima, naw‘ 2",
    en: ["What is the majority view of hadith scholars on the relative rank of the Ṣaḥīḥs of al-Bukhārī and Muslim?", ["Al-Bukhārī’s is generally considered more authentic, though some Maghribi scholars preferred Muslim’s for its arrangement and lack of repetition", "Muslim’s is more authentic by consensus", "They are equal in every respect by consensus", "Neither is regarded as authentic"], "The majority holds al-Bukhārī’s Ṣaḥīḥ above Muslim’s because of its stricter conditions (proof of meeting) and the greater precision of its narrators. Some Maghribi scholars and Abū ʿAlī al-Naysābūrī in one report preferred Muslim’s, and Ibn al-Ṣalāḥ says Muslim’s book has a better arrangement. Both are received with acceptance by the Umma."],
    de: ["Was ist die Mehrheitsansicht der Hadithgelehrten zum relativen Rang der Ṣaḥīḥs von al-Buḫārī und Muslim?", ["Al-Buḫārīs gilt im Allgemeinen als authentischer, doch manche maghrebinische Gelehrte zogen Muslims wegen der Anordnung und des Fehlens von Wiederholungen vor", "Muslims ist einhellig authentischer", "Sie sind einhellig in jeder Hinsicht gleich", "Keines gilt als authentisch"], "Die Mehrheit stellt al-Buḫārīs Ṣaḥīḥ über Muslims wegen der strengeren Bedingungen (Nachweis der Begegnung) und der größeren Präzision seiner Überlieferer. Manche maghrebinische Gelehrte und Abū ʿAlī an-Naisābūrī nach einem Bericht zogen Muslims vor, und Ibn aṣ-Ṣalāḥ sagt, Muslims Buch habe die bessere Anordnung. Beide wurden von der Umma mit Annahme aufgenommen."],
    ar: ["ما رأي أكثر المحدثين في المفاضلة بين صحيحي البخاري ومسلم؟", ["يُعدّ صحيح البخاري عمومًا أصح، وإن فضّل بعض علماء المغرب صحيح مسلم لحسن ترتيبه وقلة تكراره", "صحيح مسلم أصح بالإجماع", "هما متساويان من كل وجه بالإجماع", "لا يُعدّ أيٌّ منهما صحيحًا"], "قدّم الجمهور صحيح البخاري على مسلم لشدة شرطه (اشتراط ثبوت اللقاء) وزيادة ضبط رجاله، وفضّل بعض المغاربة وأبو علي النيسابوري في رواية صحيح مسلم، ويقول ابن الصلاح إن كتاب مسلم أحسن ترتيبًا، وتلقتهما الأمة بالقبول."] },

  { id: "xhd-037", s: "hadith", g: 4, d: 7, t: ["talaqqi-bil-qabul", "ijma-on-sahihayn"], tr: ["comparative"], src: "Ibn al-Ṣalāḥ, Muqaddima, naw‘ 2; al-Nawawī, al-Taqrīb; Ibn Ḥajar, Nuzhat al-Naẓar",
    en: ["Ibn al-Ṣalāḥ held that the hadith in the Ṣaḥīḥayn yield certain knowledge. What did al-Nawawī say, and what other views exist?", ["Al-Nawawī said they yield probable knowledge (ẓann), as for all single-narrator reports, while Ibn Ḥajar supported the view that the Umma’s acceptance gives certainty for what is not criticised", "Al-Nawawī said they give no knowledge", "Al-Nawawī said they are all mutawātir", "Everyone agreed on certain knowledge"], "Ibn al-Ṣalāḥ said that what both al-Bukhārī and Muslim agree on yields certain knowledge because the Umma accepted it. Al-Nawawī in al-Taqrīb disagreed, holding that a single-narrator report yields only probable knowledge, though the two books are of the highest grade. Ibn Ḥajar supported the former view for what the critics did not criticise, so the topic remains debated."],
    de: ["Ibn aṣ-Ṣalāḥ vertrat, dass die Hadithe der Ṣaḥīḥain sicheres Wissen liefern. Was sagte an-Nawawī, und welche anderen Ansichten gibt es?", ["An-Nawawī sagte, sie lieferten wahrscheinliches Wissen (ẓann) wie alle Einzelüberlieferungen, während Ibn Ḥaǧar die Ansicht stützte, die Annahme durch die Umma gebe Gewissheit für das, was nicht kritisiert wurde", "An-Nawawī sagte, sie lieferten kein Wissen", "An-Nawawī sagte, alle seien mutawātir", "Alle stimmten auf sicheres Wissen überein"], "Ibn aṣ-Ṣalāḥ sagte, was al-Buḫārī und Muslim beide überliefern, liefere sicheres Wissen, weil die Umma es annahm. An-Nawawī widersprach in at-Taqrīb und hielt, ein Einzelbericht liefere nur wahrscheinliches Wissen, obwohl die beiden Bücher höchsten Grades sind. Ibn Ḥaǧar stützte die erstere Ansicht für das, was die Kritiker nicht bemängelten, das Thema bleibt daher umstritten."],
    ar: ["رأى ابن الصلاح أن أحاديث الصحيحين تفيد العلم القطعي، فماذا قال النووي وما الأقوال الأخرى؟", ["قال النووي إنها تفيد الظن الراجح كسائر الآحاد، ونصر ابن حجر القول بأن تلقي الأمة بالقبول يفيد القطع فيما لم يُنتقد", "قال النووي إنها لا تفيد علمًا", "قال النووي إنها كلها متواترة", "اتفق الجميع على إفادة العلم القطعي"], "قال ابن الصلاح إن ما اتفق عليه البخاري ومسلم يفيد العلم القطعي لتلقي الأمة له بالقبول، وخالفه النووي في «التقريب» فرأى أن خبر الواحد لا يفيد إلا الظن وإن كان الكتابان في أعلى الدرجات، ونصر ابن حجر القول الأول فيما لم ينتقده النقاد، فالمسألة خلافية."] },

  { id: "xhd-038", s: "hadith", g: 4, d: 7, t: ["daraqutni", "criticisms-of-sahihayn"], src: "al-Dāraquṭnī, al-Istidrākāt wa-l-Tatabbuʿ; Ibn Ḥajar, Hady al-Sārī, muqaddima (chapter on the criticised hadith)",
    en: ["What is al-Dāraquṭnī’s al-Tatabbuʿ, and how did Ibn Ḥajar respond?", ["A book listing about 200 hadith in the Ṣaḥīḥayn he criticised for chain or text; Ibn Ḥajar answered most of the criticisms in the introduction to Fatḥ al-Bārī (Hady al-Sārī)", "A book listing hadith missing from the Ṣaḥīḥayn, which Ibn Ḥajar adopted", "A book of poetry", "A compilation of the sermons of the caliphs"], "Al-Dāraquṭnī (d. 385 AH) wrote al-Istidrākāt wa-l-Tatabbuʿ, criticising a number of hadith in the Ṣaḥīḥayn, said to be about 200, for weaknesses such as disagreements in the chain or breaks. Ibn Ḥajar in Hady al-Sārī reviewed them, answering most and conceding that a few criticisms had weight. Most of these hadith have supporting chains."],
    de: ["Was ist ad-Dāraquṭnīs at-Tatabbuʿ, und wie antwortete Ibn Ḥaǧar?", ["Ein Buch, das etwa 200 Hadithe der Ṣaḥīḥain wegen Kette oder Text kritisiert; Ibn Ḥaǧar beantwortete die meisten Kritikpunkte in der Einleitung zu Fatḥ al-Bārī (Hady as-Sārī)", "Ein Buch, das in den Ṣaḥīḥain fehlende Hadithe aufführt und das Ibn Ḥaǧar übernahm", "Ein Gedichtband", "Eine Sammlung der Predigten der Kalifen"], "Ad-Dāraquṭnī (gest. 385 n. H.) schrieb al-Istidrākāt wa-t-Tatabbuʿ und kritisierte eine Anzahl von Hadithen in den Ṣaḥīḥain, wohl etwa 200, wegen Schwächen wie Abweichungen in der Kette oder Brüchen. Ibn Ḥaǧar prüfte sie in Hady as-Sārī, beantwortete die meisten und räumte ein, dass einige Kritikpunkte Gewicht hatten. Die meisten dieser Hadithe haben stützende Ketten."],
    ar: ["ما كتاب «التتبع» للدارقطني وكيف ردّ عليه ابن حجر؟", ["كتاب ينتقد نحو مئتي حديث في الصحيحين في إسنادها أو متنها، وأجاب ابن حجر عن أكثرها في مقدمة فتح الباري (هدي الساري)", "كتاب يذكر أحاديث فاتت الصحيحين وقد تبناه ابن حجر", "ديوان شعر", "مجموعة خطب الخلفاء"], "ألّف الدارقطني (ت 385هـ) «الاستدراكات والتتبع» انتقد فيه عددًا من أحاديث الصحيحين يقال نحو مئتين لعلل كاختلاف في السند أو انقطاع، وفحصها ابن حجر في «هدي الساري» فأجاب عن أكثرها وسلّم بوزن بعض الانتقادات، ولأكثر هذه الأحاديث طرق تعضدها."] },

  { id: "xhd-039", s: "hadith", g: 4, d: 6, t: ["fath-al-bari", "commentaries"], src: "Ibn Ḥajar, Fatḥ al-Bārī; al-ʿAynī, ʿUmdat al-Qārī; al-Qasṭallānī, Irshād al-Sārī; al-Nawawī, al-Minhāj",
    en: ["Which commentary matches which book: Fatḥ al-Bārī, ʿUmdat al-Qārī and al-Minhāj?", ["Fatḥ al-Bārī (Ibn Ḥajar) and ʿUmdat al-Qārī (al-ʿAynī) on al-Bukhārī; al-Minhāj (al-Nawawī) on Muslim", "All three on Muslim", "Fatḥ al-Bārī on Muslim; ʿUmdat al-Qārī on al-Tirmidhī; al-Minhāj on al-Bukhārī", "All three on Muwaṭṭaʾ Mālik"], "Ibn Ḥajar’s Fatḥ al-Bārī is the best-known commentary on al-Bukhārī, and al-ʿAynī’s ʿUmdat al-Qārī is an extensive rival work, written partly in response to Ibn Ḥajar. Al-Nawawī’s al-Minhāj fī Sharḥ Ṣaḥīḥ Muslim ibn al-Ḥajjāj is the standard commentary on Muslim. Al-Qasṭallānī’s Irshād al-Sārī is another commentary on al-Bukhārī."],
    de: ["Welcher Kommentar gehört zu welchem Buch: Fatḥ al-Bārī, ʿUmdat al-Qārī und al-Minhāǧ?", ["Fatḥ al-Bārī (Ibn Ḥaǧar) und ʿUmdat al-Qārī (al-ʿAinī) zu al-Buḫārī; al-Minhāǧ (an-Nawawī) zu Muslim", "Alle drei zu Muslim", "Fatḥ al-Bārī zu Muslim; ʿUmdat al-Qārī zu at-Tirmiḏī; al-Minhāǧ zu al-Buḫārī", "Alle drei zum Muwaṭṭaʾ Mālik"], "Ibn Ḥaǧars Fatḥ al-Bārī ist der bekannteste Kommentar zu al-Buḫārī, und al-ʿAinīs ʿUmdat al-Qārī ist ein umfangreiches Konkurrenzwerk, teilweise als Antwort auf Ibn Ḥaǧar geschrieben. An-Nawawīs al-Minhāǧ fī Šarḥ Ṣaḥīḥ Muslim ibn al-Ḥaǧǧāǧ ist der Standardkommentar zu Muslim. Al-Qasṭallānīs Iršād as-Sārī ist ein weiterer Kommentar zu al-Buḫārī."],
    ar: ["أي شرح يقابل أي كتاب: فتح الباري وعمدة القاري والمنهاج؟", ["فتح الباري (ابن حجر) وعمدة القاري (العيني) على البخاري، والمنهاج (النووي) على مسلم", "الثلاثة على مسلم", "فتح الباري على مسلم وعمدة القاري على الترمذي والمنهاج على البخاري", "الثلاثة على موطأ مالك"], "«فتح الباري» لابن حجر أشهر شروح البخاري، و«عمدة القاري» للعيني شرح واسع مناظر له وُضع جزئيًّا ردًّا عليه، و«المنهاج في شرح صحيح مسلم بن الحجاج» للنووي هو الشرح المعتمد لمسلم، و«إرشاد الساري» للقسطلاني شرح آخر للبخاري."] },

  { id: "xhd-040", s: "hadith", g: 4, d: 7, t: ["ahl-al-hadith", "authentication-methods"], src: "al-Khaṭīb al-Baghdādī, al-Jāmiʿ li-Akhlāq al-Rāwī wa-Ādāb al-Sāmiʿ; Ibn Rajab, Sharḥ ʿIlal al-Tirmidhī",
    en: ["What does the method of ‘collecting the chains’ (jamʿ al-ṭuruq) mean in the work of the early critics?", ["Gathering all the versions of a hadith and comparing them to find errors, additions and breaks, as ʿAlī ibn al-Madīnī and Yaḥyā ibn Maʿīn did", "Collecting the poetry of a narrator", "Gathering the Prophet’s sayings in one book without chains", "Collecting the fees paid to narrators"], "A famous saying attributed to ʿAlī ibn al-Madīnī and Yaḥyā ibn Maʿīn is that if you do not collect the routes of a hadith you will not understand its error. By bringing together all routes and comparing wordings and narrators, the critic detects who made a mistake and whether a hadith is firmly supported. This method is the foundation of ʿilal-criticism, as Ibn Rajab explains."],
    de: ["Was bedeutet die Methode des ‚Sammelns der Ketten‘ (ǧamʿ aṭ-ṭuruq) im Werk der frühen Kritiker?", ["Alle Fassungen eines Hadith zusammentragen und vergleichen, um Fehler, Zusätze und Brüche zu finden, wie ʿAlī ibn al-Madīnī und Yaḥyā ibn Maʿīn es taten", "Die Gedichte eines Überlieferers sammeln", "Aussprüche des Propheten ohne Ketten in einem Buch sammeln", "Die an Überlieferer gezahlten Gebühren sammeln"], "Ein berühmter Ausspruch, ʿAlī ibn al-Madīnī und Yaḥyā ibn Maʿīn zugeschrieben, lautet, wer die Wege eines Hadith nicht sammle, verstehe seinen Fehler nicht. Indem der Kritiker alle Wege zusammenbringt und Wortlaute und Überlieferer vergleicht, erkennt er, wer sich irrte und ob ein Hadith fest gestützt ist. Diese Methode ist die Grundlage der ʿIlal-Kritik, wie Ibn Raǧab erläutert."],
    ar: ["ماذا يعني منهج «جمع الطرق» في عمل النقاد الأوائل؟", ["جمع كل روايات الحديث ومقارنتها لكشف الأخطاء والزيادات والانقطاعات كما فعل علي بن المديني ويحيى بن معين", "جمع شعر الراوي", "جمع أقوال النبي ﷺ في كتاب دون أسانيد", "جمع الأجور المدفوعة للرواة"], "يُنسب إلى علي بن المديني ويحيى بن معين قولهما إن الحديث إذا لم تجمع طرقه لم يُعرف خطؤه، فبجمع الطرق ومقارنة الألفاظ والرواة يكتشف الناقد من أخطأ ومدى ثبوت الحديث، وهذا المنهج أساس نقد العلل كما يبين ابن رجب."] },
];
